window.LQ_SOL=window.LQ_SOL||{};window.LQ_SOL["2019年第十届"]={"2299":[{"aid":"109165","title":"完全二叉树的权值（双指针）","date":"2025-04-21","likes":0,"views":460,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-完全二叉树的权值\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\n#define int long long\nint n;\nint a[100005];\nsigned main()\n{\n    cin>>n;\n    int depth=0,ma=0;\n    for(int i=1;i<=n;i++) cin>>a[i];\n    for(int d=1,i=1;i<=n;i*=2,d++){\t//d为当前层数，i为每一层的首元素\n        int sum=0;\t//计算当前层的权值\n        for(int j=i;j<2*i&&j<=n;j++){\t//j为每一层的元素\n            sum+=a[j];\n        }\n        if(sum>ma){\n            ma=sum;\n            depth=d;\n        }\n    }\n    cout<<depth;\n    return 0;\n}\n\n E 正文"},{"aid":"103633","title":"java暴力打表，幼儿园小班都能看懂的解法！","date":"2024-03-19","likes":0,"views":665,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-完全二叉树的权值\n\n Server-side output Markdown text\n# 思路\n- 用sum保存每一层的总和，max保存此时的最大值。遇到每一层最后一个数字时更新max和sum。\n- 用一个数组保存每一层最后一个数字的下标（下标从1开始）\n# 代码\n```\npublic static void main(String[] args) {\n\t\tScanner sc = new Scanner(System.in);\n\t\tint n = sc.nextInt();\n\t\tint[] e = {1,3,7,15,31,63,127,255,511,1023,2047,4095,8191,16383,32767,65535,131071};  //每一层最后一个数字的下标\n\t\tlong sum=0,max=0;\n\t\tint index = 0;\n\t\tint k=0,x=0;  //k用来记录当前求的是第几层\n\t\tfor(int i=1;i<=n;i++) {\n\t\t\tx = sc.nextInt();\n\t\t\tsum+=x;\t\t//sum统计每一层的总和\n\t\t\t//当遇到第k层最后一个数字或输入结束时更新最大值和层数index\n\t\t\tif(i == e[k] || i==n) {\n\t\t\t\tif(sum > max)\n\t\t\t\t\tindex = k;\n\t\t\t\tmax = Math.max(max, sum);\n\t\t\t\tsum=0;  //清空这一层的和\n\t\t\t\tk++;  //表示进入下一层\n\t\t\t}\n\t\t}\n\t\tSystem.out.println(index+1);  //k从0开始，所以最终的index要+1\n\t}\n```\n\n E 正文"},{"aid":"97705","title":"完全二叉树的权值 c++超简洁","date":"2023-07-22","likes":0,"views":746,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-完全二叉树的权值\n\n解题思路:因为深度i是深度i-1的2倍，所以定义一个s来表示每层深度的结点数\n\n注意事项:需要了解二叉树的基本概念\n\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\nlong long n,a[1000000],x[1000000],s=1,z=1,zd,q,w=1;\nint main(){\ncin>>n;                                                  //结点数\n\tfor(int i=1;i<=n;i++)\n\tcin>>a[i];                                              //输出每个节点的大小\n\tfor(int j=1;j<=n;j++){\n\t\tfor(int i=1;i<=s;i++){                           //s是第就层的结点数\n\t\t\tx[w]+=a[z];                                          //w表示层数，换成j也行\n\t\t\tz++;                                                    //记录结点数\n\t\t\tif(z>n){                                               //如果大于总结点数开始判断\n\t\t\t\tif(x[w]>zd)zd=x[w],q=w;                   //如果第w层的权值大于最大的权值，q=w\n\t\t\t\tcout<<q;                                           //输出深度\n\t\t\t\treturn 0;\n\t\t\t}\n\t\t}\n\t\tif(x[w]>zd)zd=x[w],q=w;                 //如果第w层的权值大于最大的权值，q=w\n\t\ts=s*2;                                             //s=下一深度的结点数\n\t\tw++;                                              //深度+1\n\t}\n\treturn 0;\n}\n\n E 正文"},{"aid":"95656","title":"前缀和,区分完全二叉树和满二叉树的概念","date":"2023-04-05","likes":0,"views":775,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-完全二叉树的权值\n\n解题思路:完全二叉树最后一层是有可能不满的\n\n注意事项:\n\n参考代码:\nn=int(input())\na=[0]+list(map(int,input().split()))\ns=[0]+[a[1]]\nfor i in range(1,n+1):\n    a[i]+=a[i-1]\nt=3\nwhile t<=n:\n    s.append(a[t]-a[t//2])\n    if t==n:\n        break\n    t=t*2+1\nif t>n:\n    s.append(a[n]-a[t//2])\nt=float('inf')\nq=[]\nfor i in range(len(s)):\n    if s[i]==max(s):\n        q.append(i)\nprint(min(q))\n\n E 正文"},{"aid":"94876","title":"蓝桥杯2019年第十届省赛真题-完全二叉树的权值(双指针)","date":"2023-03-15","likes":0,"views":846,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-完全二叉树的权值\n\n Server-side output Markdown text\n####解题思路\n完全二叉树特点：完全二叉树第 i 层至多有 2^(i-1) 个节点。\n可以记录每一层的权值之和，再判断哪一层的权值之和最大。\n\n####参考代码\n```cpp\n#include <iostream>\n#include <cstring>\n#include <algorithm>\n#include <cmath>\n\nusing namespace std;\n\n// 开 long long 若是有 1e5 数值，每个都为 1e5 则会爆int\ntypedef long long LL;\nconst int INF = 0x3f3f3f3f;\nLL a[1 << 17], cnt[20]; // 2^17 > 1e5, cnt 开到 20 防止数组越界\nint n;\n\nint main()\n{\n    cin >> n;\n    for (int i = 1; i <= n; i ++ )  scanf(\"%lld\", &a[i]);\n\n    int i = 1, j = 0;\n    while (i <= n)\n    {\n        ++ j;\n        while (i < pow(2, j)) cnt[j] += a[i ++ ];\n\t\t// 每一层都有 2^(j - 1) 到 2^j - 1\n    }\n\n    LL maxv = -INF, res = 0; // 权值之和可能为负数，maxv 取最小值\n    for (int i = 1; i <= j; i ++ )\n        if (maxv < cnt[i])\n            maxv = cnt[i],\n            res = i;\n\n    cout << res;\n\n    return 0;\n}\n```\n\n E 正文"}],"2300":[{"aid":"104257","title":"蓝桥杯2019年第十届省赛真题-外卖店优先级","date":"2024-04-08","likes":0,"views":576,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-外卖店优先级\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\npriority_queue<int,vector<int>,greater<int> >q[100005];\nint main()\n{\n\tint n,m,t;\n\tcin>>n>>m>>t;\n\tfor(int i=0;i<m;i++)\n\t{\n\t\tint x,y;\n\t\tcin>>x>>y;\n\t\tq[y].push(x);\n\t}\n\tint ans;\n\tans=0;\n\tfor(int i=1;i<=n;i++)\n\t{\n\t\tint f;\n\t\tf=0;\n\t\tint l;\n\t\tl=0;\n\t\tint sum;\n\t\tsum=0;\n\t\twhile(!q[i].empty())\n\t\t{\n\t\t\tint r;\n\t\t\tr=q[i].top();\n\t\t\tint a;\n\t\t\tif(l!=r)sum-=(r-l-1);\n\t\t\tif(sum<0)sum=0;\n\n\t\t\tif(f&&sum<=3)\n\t\t\t{\n\t\t\t\tf=0;\n\t\t\t}\n\t\t\tsum+=2;\n\t\t\tif(!f&&sum>5)\n\t\t\t{\n\t\t\t\tf=1;\n\t\t\t}\n\t\t\tl=r;\n\t\t\t//cout<<r<<endl;\n\t\t\tq[i].pop();\n\t\t}\n\t\tsum-=t-l;\n\t\t//cout<<sum<<endl;\n\t\tif(f&&sum<=3)\n\t\t{\n\t\t\tf=0;\n\t\t}\n\t\tif(f)ans++;\n\t}\n\tcout<<ans;\n\treturn 0;\n}\n\n E 正文"},{"aid":"104111","title":"python yydsyyds","date":"2024-04-02","likes":0,"views":575,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-外卖店优先级\n\n解题思路:\n\n注意事项:\n\n参考代码:\nfirst = input()\nn,m,T=[int (i) for i in first.split()]\na=[]\n\nfor i in range(m):\n    a.append([int(i) for i in input().split()])\n\n#对订单的的时间进行排序，目的是算出当前订单与上一回订单之间的间隔\n#从未计算出这家店没有订单的时候优先级下降数\n#即：prior[idd] -= tt-order[idd]-1\na=sorted(a,key=lambda a:a[0])\n\norder=[]#订单的时刻\nprior=[]#优先级的分数\nflag=[]#是否在优先缓存中\n#初始化为0\norder=[0 for i in range(n+1)]\nprior=[0 for i in range(n+1)]\nflag=[0 for i in range(n+1)]\n\n#遍历每一条订单信息\nfor i in range(m):\n    tt=a[i][0]\n    idd=a[i][1]\n    #如果当前订单的时间不等于上次的订单\n    #由题意每过一秒优先级减1，所以优先级减去间隔\n    if tt != order[idd]:\n        prior[idd] -= tt-order[idd]-1\n    if prior[idd]<0: prior[idd]=0#优先级最低为0\n    if prior[idd]<=3: flag[idd]=0\n    prior[idd]+=2  #有订单则优先级加2\n    if prior[idd]>5: flag[idd]=1\n    order[idd]=tt  #记录这次订单的时间，下此迭代使用\n\n#处理到了T时刻的情况\nfor i in range(1,n+1):\n    #如果最后一个订单不是T时刻的\n    #要减去最后一趟订单时间与t的差的绝对值\n    if order[i] <T:\n        prior[i]-=T-order[i]\n        if prior[i]<=3: flag[i]=0\n\n#遍历求在缓存区的商家个数\nans=0\nfor i in range(n+1):\n    if( flag[i]>0):\n        ans+=1\nprint(ans)\n\n E 正文"},{"aid":"89503","title":"简单的模拟题，时间复杂度O(n+mlogm)","date":"2022-08-18","likes":0,"views":693,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-外卖店优先级\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\n#define maxn 100010\n#define maxm 100010\n#define maxt 100010\npair<int,int> a[maxm];//a.first是时刻，a.second是收到外卖的外卖店的编号\nint n,m,t,ans;\nint grade[maxn],pastt[maxn];//店的优先级,每个店收到上一单的时刻\nbool cmp(pair<int,int>& x,pair<int,int>& y){\n    return x.first<y.first;//按时刻从小到大排序\n}\nint main(){\n    scanf(\"%d%d%d\",&n,&m,&t);\n    for(int i=1;i<=m;i++){\n        scanf(\"%d%d\",&a[i].first,&a[i].second);\n    }\n    sort(a+1,a+1+m,cmp);\n    int ts,id;\n    for(int i=1;i<=m;i++){\n        ts=a[i].first;id=a[i].second;\n        grade[id]=2+max(0,grade[id]-max(0,ts-1-pastt[id]));\n        pastt[id]=ts;\n    }\n    int tmpgrade;\n    for(int i=1;i<=n;i++){\n        tmpgrade=max(0,grade[i]-(t-pastt[i]));\n        if(tmpgrade>5)ans++;\n        else if(tmpgrade>3&&grade[i]>5)ans++;\n    }\n    printf(\"%d\",ans);\n    system(\"pause\");\n    return 0;\n}\n\n E 正文"},{"aid":"85923","title":"外卖店优先级（减少内存，优化时间）java","date":"2022-03-29","likes":0,"views":1134,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-外卖店优先级\n\n Server-side output Markdown text\n### 注意事项\n同一时刻可能有多个店铺有订单，同一时刻同一店铺可能有多个订单\n### 解题思路\n该题数据有点大，如果直接用HashMap,List等集合可能会超时，无疑数组是最快的\n我最开始的思路是建立一个二维数组，横坐标存时刻，纵坐标存每个店铺，值就是该时刻该店铺接到的订单数，于是外层循环遍历时刻，内层循环遍历店铺，以此来进行模拟，很可惜，内存超了，换个思路，也就是下面的参考代码，将二维换成两个一维，\n索引为订单编号，两个一维的值分别为时刻和店铺，之后外层依然遍历时刻，内层遍历订单编号，，，，，，，具体见下面参考代码\n### 参考代码\n```java\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.util.HashSet;\nimport java.util.Set;\nimport java.util.StringTokenizer;\n\npublic class Main {\n\tstatic BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));\n\tstatic StringTokenizer stringTokenizer = new StringTokenizer(\"\");\n\n\tstatic String nextLine() throws IOException {\n\t\treturn bufferedReader.readLine();\n\t}\n\n\tstatic String next() throws IOException {\n\t\twhile (!stringTokenizer.hasMoreTokens()) {\n\t\t\tstringTokenizer = new StringTokenizer(bufferedReader.readLine());\n\t\t}\n\t\treturn stringTokenizer.nextToken();\n\t}\n\n\tstatic int nextInt() throws NumberFormatException, IOException {\n\t\treturn Integer.parseInt(next());\n\t}\n\n\tpublic static void main(String[] args) throws NumberFormatException, IOException {\n\n\t\tint n = nextInt();\n\t\t// 记录每家店铺的优先级，从1到n（包括n）\n\t\tint[] shop = new int[n + 1];\n\t\t// m个订单\n\t\tint m = nextInt();\n\t\t// 索引为订单编号\n\t\t// 值为该订单的时刻\n\t\tint ot[] = new int[m];\n\t\t// 值为该订单对应的店铺\n\t\tint os[] = new int[m];\n\t\t// t个时刻\n\t\tint t = nextInt();\n\t\tSet<Integer> hc = new HashSet<>();\n\t\tfor (int i = 0; i < m; i++) {\n\t\t\tot[i] = nextInt();\n\t\t\tos[i] = nextInt();\n\t\t}\n\t\tfor (int i = 1; i <= t; i++) {\n\t\t\tint[] vic = new int[n + 1];\n\t\t\t// 遍历订单\n\t\t\tfor (int j = 0; j < m; j++) {\n\t\t\t\t// 该时刻有订单\n\t\t\t\tif (ot[j] == i) {\n\t\t\t\t\t// 每有一单优先级加 2\n\t\t\t\t\tshop[os[j]] += 2;\n\t\t\t\t\tvic[os[j]] = 1;\n\t\t\t\t}\n\t\t\t}\n\t\t\t// 遍历店铺\n\t\t\tfor (int j = 1; j <= n; j++) {\n\t\t\t\t// 如果该店铺已经访问过且店铺优先级大于5\n\t\t\t\tif (vic[j] == 1 && shop[j] > 5) {\n\t\t\t\t\thc.add(j);\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\t// 如果该店铺已经访问过，continue\n\t\t\t\tif (vic[j] != 0) {\n\t\t\t\t\tcontinue;\n\t\t\t\t}\n\t\t\t\t// 店铺未访问\n\t\t\t\tshop[j] -= 1;\n\t\t\t\t// 如果店铺优先级小于等于3且在缓存中存在，移出缓存\n\t\t\t\tif (shop[j] <= 3 && hc.contains(j)) {\n\t\t\t\t\thc.remove(j);\n\t\t\t\t}\n\n\t\t\t\tif (shop[j] < 0) {\n\t\t\t\t\tshop[j] = 0;\n\t\t\t\t}\n\n\t\t\t}\n\t\t}\n\t\tSystem.out.println(hc.size());\n\t}\n}\n```\n\n E 正文"},{"aid":"84629","title":"蓝桥杯2019年第十届真题-外卖店优先级-题解（C++代码）","date":"2022-03-01","likes":0,"views":615,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-外卖店优先级\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<iostream>\n#include<algorithm>\n#include<vector>\nusing namespace std;\nconst int N = 1e5 + 10;\nint n, m, t, cnt = 0;\nbool cmp(vector<int> a, vector<int> b) {\n    if (a[0] != b[0]) return a[0] < b[0];\n    else return a[1] < b[1];\n}\nint main()\n{\n    cin >> n >> m >> t;\n    vector<vector<int> > num(m, vector<int>(2));\n    vector<int> dp(n + 1, 0), store(n + 1, 0);\n    vector<bool> ans(n + 1, 0);\n    for (int i = 0; i < m; i++) cin >> num[i][0] >> num[i][1];\n    sort(num.begin(), num.end(), cmp);\n    for (int i = 0; i < m; i++) {\n        int sub = num[i][0] - dp[num[i][1]] - 1;\n        if (sub > 0) store[num[i][1]] = store[num[i][1]] - sub > 0 ? store[num[i][1]] - sub : 0;\n        if (store[num[i][1]] <= 3 && ans[num[i][1]]) ans[num[i][1]] = false;\n        store[num[i][1]] += 2;\n        if (store[num[i][1]] > 5 && !ans[num[i][1]]) ans[num[i][1]] = true;\n        dp[num[i][1]] = num[i][0];\n    }\n    for (int i = 1; i <= n; i++) {\n        if (ans[i]) {\n            int sub = t - dp[i];\n            store[i] -= sub;\n            if (store[i] > 3) cnt++;\n        }\n    }\n    cout << cnt;\n    return 0;\n}\n\n E 正文"}],"2301":[{"aid":"108749","title":"蓝桥杯2019年第十届省赛真题-修改数组  巧用STL","date":"2025-03-09","likes":0,"views":526,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-修改数组\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include\"bits/stdc++.h\"\nusing namespace std;\n#define ll long long\nconst ll N=1e6+1e5+5;\nset<ll> s;\nll n;\nint main(){\n    for(ll i=1;i<N;i++)s.insert(i);\n    scanf(\"%lld\",&n);\n    for(ll i=1;i<=n;i++){\n        ll x;\n        scanf(\"%lld\",&x);\n        auto kk=s.lower_bound(x);\n        s.erase(kk);\n        printf(\"%lld \",*kk);\n    }\n    return 0;\n}\n\n E 正文"},{"aid":"99564","title":"并查集。。。。。。","date":"2023-11-08","likes":0,"views":578,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-修改数组\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<iostream>\n#include<algorithm>\nusing namespace std;\nconst int N=1e6+10;\nint p[N];\nint n;\nint find(int x)\n{\nif(p[x]!=x)p[x]=find(p[x]);\nreturn p[x];\n\n}\nint main()\n{\n    ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);\n    cin>>n;\n    int a;\n    for(int i=1;i<=N;++i)p[i]=i;\n    for(int i=1;i<=n;++i)\n    {\n      cin>>a;\n      a= find(a);\n      cout<<a<<\" \";\n      p[a]=a+1;//把a接到比自己大一的结点上,下次在碰到a直接输出a+1\n               //注意find()函数有路径压缩,如已有2,3,4,5,经过路径压缩它们全部接到6,下次再碰到它们其中一个直接输出6\n\n    }\n    return 0;\n\n}\n\n E 正文"},{"aid":"85223","title":"题解 2301: 蓝桥杯2019年第十届省赛真题-修改数组-java","date":"2022-03-14","likes":0,"views":930,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-修改数组\n\n解题思路:\n\n注意事项:\n\n参考代码:\nimport java.util.Scanner;\npublic class Main {\n\tpublic static void main(String[] args) {\n\t\tScanner sc=new Scanner(System.in);\n\t\tint  n=sc.nextInt();\n\t\tint[] count=new int[1000001]; //记录每一个Ai出现的次数\n\t\tlong[] arr=new long[n];  //最终数组\n\t\tfor(int i=0;i<n;i++){\n\t\t\tint num=sc.nextInt();\n\t\t\tif(count[num]==0){    //出现0次输出arr[i],并记录count[num]++\n\t\t\t\tarr[i]=num;\n\t\t\t\tcount[num]++;\n\t\t\t}else{                 //Ai已经出现过，循环找到count[num]为0的num，利用num+=count[num]-1;减少循环次数，以免超时\n\t\t\t\twhile(count[num]!=0){\n\t\t\t\t\tcount[num]++; //只要出现过就++\n\t\t\t\t\tnum+=count[num]-1; //如果大于1说明已经加过了，直接count[num]-1\n\t\t\t\t}\n\t\t\t\tcount[num]++;\n\t\t\t\tarr[i]=num;\n\t\t\t}\n\t\t\tSystem.out.print(arr[i]+\" \");\n\t\t}\n\t}\n}\n\n E 正文"},{"aid":"83111","title":"Benjam1n：蓝桥杯2019年第十届省赛真题-修改数组（Java代码）","date":"2022-01-25","likes":0,"views":613,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-修改数组\n\n解题思路:\n\n注意事项:\n\n参考代码:\n\tpublic static void main(String[] args) {\n\t\tScanner in = new Scanner(System.in);\n\t\tint n = in.nextInt();\n\t\tint[] vis = new int[100001];\n\t\tint[] nums = new int[n];\n\t\tfor(int i=0;i<n;i++)nums[i]=in.nextInt();\n\t\tfor(int i=0;i<n;i++) {\n\t\t\twhile(vis[nums[i]]==1) {\n\t\t\t\tnums[i]++;\n\t\t\t}\n\t\t\tvis[nums[i]]=1;\n\t\t}\n\t\tfor(int i=0;i<n;i++)System.out.print(nums[i]+\" \");\n\t}\n\n E 正文"},{"aid":"80861","title":"蓝桥杯2019年第十届省赛真题-修改数组（路径压缩+卡cin问题）","date":"2021-11-04","likes":0,"views":1061,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-修改数组\n\n解题思路:\n类似于并查集的思想进行路径压缩\n注意事项:\n\n参考代码:\n\nAC代码\n\n#include\nusing namespace std;\nint used[1000005], n, num;\n\nint findnext(int x) {\n\tif (!used[x]) return x;\n\tif (used[x] == 1) {\n\t\tused[x] = findnext(x + 1);\n\t}\n\telse\n\t{\n\t\tused[x] = findnext(used[x]);\n\t}\n\treturn used[x];\n}\nint main() {\n\tscanf(\"%d\", &n);\n\tfor (int i = 1; i <=n ; i++)\n\t{\n\t\tscanf(\"%d\", &num);\n\t\tnum = findnext(num);\n\t\tused[num] = 1;\n\t\tprintf(\"%d \", num);\n\t}\n\treturn 0;\n}\n\n被卡cin的代码，超时18%\n#include\nusing namespace std;\nint used[1000005], n, num;\n\nint findnext(int x) {\n\tif (!used[x]) return x;\n\tif (used[x] == 1) {\n\t\tused[x] = findnext(x + 1);\n\t}\n\telse\n\t{\n\t\tused[x] = findnext(used[x]);\n\t}\n\treturn used[x];\n}\nint main() {\n\tcin >> n;\n\tfor (int i = 1; i <=n ; i++)\n\t{\n\t\tcin >> num;\n\t\tnum = findnext(num);\n\t\tused[num] = 1;\n\t\tcout << num << \" \";\n\t}\n\treturn 0;\n}\n\n如果改变输出方式又能AC了\n#include\nusing namespace std;\nint used[1000005], n, num, ornums[100005];\n\nint findnext(int x) {\n\tif (!used[x]) return x;\n\tif (used[x] == 1) {\n\t\tused[x] = findnext(x + 1);\n\t}\n\telse\n\t{\n\t\tused[x] = findnext(used[x]);\n\t}\n\treturn used[x];\n}\nint main() {\n\tcin >> n;\n\tfor (int i = 1; i <=n ; i++)\n\t{\n\t\tcin >> num;\n\t\tnum = findnext(num);\n\t\tused[num] = 1;\n\t\tornums[i] = num;\n\t}\n\tfor (int i = 1; i <= n; i++)\n\t{\n\t    cout << ornums[i] << \" \";\n\t}\n\treturn 0;\n}\n\n为什么最后同样用cin，第二种输出方式能ac，我也很迷\n\n E 正文"}],"2302":[{"aid":"104194","title":"C++ 状态压缩dp","date":"2024-04-05","likes":0,"views":773,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-糖果\n\n解题思路:尝试了一下dfs只能拿到一半的分数，刚好昨天学了状压dp，每一包糖果的组合都可以用一种状态来表示。可以枚举每一种状态通过状态转移方程得到结果\n\n注意事项:\n\n参考代码:\n#include<bits/stdc++.h>\n#define INF 0x3f3f3f3f\nusing namespace std;\nint n,m,k;\nint dp[1<<20];//达到状态i所需的最少次数\nint a[110];//表示每一包糖的状态要开到110 不然会一个点过不去\nint main()\n{\n    ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);\n    cin>>n>>m>>k;//n包糖果 m种 一包k个\n    memset(dp,INF,sizeof(dp));//全都初始化成无穷大\n    for(int i=1;i<=n;i++){\n        int t=0,p=0;\n        for(int j=1;j<=k;j++){\n            cin>>p;p--;\n            t=t|(1<<p);//存储状态 注意要使用| 而不是 +\n        }\n        dp[t]=1;//表示这种状态一包即可\n        a[i]=t;//记录这包糖的状态\n    }\n    for(int i=0;i<(1<<m);i++){//枚举状态\n        for(int j=1;j<=n;j++){//枚举糖果\n            //开始状态转移 |可以看成选择这个糖果\n            dp[i|a[j]]=min(dp[i]+1,dp[i|a[j]]);\n        }\n    }\n    if(dp[(1<<m)-1]==INF){//因为状态是从0开始枚举的所以要减个1\n        cout<<\"-1\"<<endl;\n    }else{\n        cout<<dp[(1<<m)-1]<<endl;\n    }\n    return 0;\n}\n\n E 正文"},{"aid":"95306","title":"蓝桥杯2019年第十届省赛真题-糖果  状态压缩dp","date":"2023-03-26","likes":0,"views":580,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-糖果\n\n解题思路:\n\n注意事项:\n\n参考代码:\nimport java.util.Arrays;\nimport java.util.Scanner;\n\npublic class 糖果 {\n    static int[] dp = new int[(1<<21)-1];\n    public static void main(String[] args) {\n//        System.out.println(Integer.toBinaryString((1<<21)-1));\n        Scanner scanner = new Scanner(System.in);\n        int N = scanner.nextInt();\n        int M = scanner.nextInt();//口味数量\n        int K = scanner.nextInt();\n        Arrays.fill(dp,105);\n//        System.out.println(Integer.toBinaryString((1<<M)-1));\n//        System.out.println((1<<M)-1);\n        int[] candies = new int[N + 2];\n        for (int i = 1; i <= N; i++) {\n            for (int j = 1; j <= K; j++) {\n                candies[i]|=1<<(scanner.nextInt()-1);\n            }\n//            System.out.println(Integer.toBinaryString(candies[i]));\n            dp[candies[i]]=1;\n        }\n             for(int j=1;j<=N;j++){\n                 for(int i=1;i<dp.length;i++){\n                 if(dp[i]!=105)\n                     dp[i|candies[j]] = Math.min(dp[i]+1,dp[i|candies[j]]);\n             }\n         }\n//            for(int i=1;i<=31;i++)\n//                System.out.println(dp[i]);\n             if(dp[(1<<M)-1]==105)\n                 System.out.println(-1);\n             else\n                 System.out.println(dp[(1<<M)-1]);\n    }\n}\n\n E 正文"},{"aid":"85440","title":"题解 2302: 蓝桥杯2019年第十届省赛真题-糖果-状态压缩dp思想","date":"2022-03-19","likes":0,"views":1296,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-糖果\n\n解题思路:状态压缩将每种状态用二进制的形式表示\n例如第一包糖果：1 1 2\n可以表示为：00011\n表示第一种和第二种口味都有\n\n而11111表示五种口味都有\n\ndp[j]:表示当j状态的时，最少需要几包糖果构成\n\n状态转移方程：\nif(dp[j]==0){\n        \t\t\tcontinue;\n        \t\t}else{\n        \t\t\tif(dp[j | mzhuangtai[i]]==0){\n        \t\t\t\tdp[j | mzhuangtai[i]]=dp[j]+dp[mzhuangtai[i]];\n        \t\t\t}else{\n        \t\t\t\tdp[j | mzhuangtai[i]]=Math.min(dp[j | mzhuangtai[i]], dp[j]+dp[mzhuangtai[i]]);\n        \t\t\t}\n}\n\n模拟一下，一个一个进行或运算，最后找到最佳值\n\n参考代码:\nimport java.util.Scanner;\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc=new Scanner(System.in);\n        int n=sc.nextInt(),m=sc.nextInt(),k=sc.nextInt(); //n包糖果，m种类，每包k个糖\n        int[] dp=new int[(1<<m)-1+1];  //dp[i]=value: i状态口味需要value包糖果构成\n        int[] mzhuangtai=new int[n];\n        for(int i=0;i<n;i++){\n        \tfor(int j=0;j<k;j++){\n        \t\tint weidao=sc.nextInt();\n        \t\tmzhuangtai[i] |= 1<<weidao-1;     //按位或运算符优先级 低于 加减运输符\n        \t}\n        \tdp[mzhuangtai[i]]=1;\n        }\n        for(int i=0;i<n;i++){\n        \tfor(int j=0;j<(1<<m);j++){\n        \t\tif(dp[j]==0){\n        \t\t\tcontinue;\n        \t\t}else{\n        \t\t\tif(dp[j | mzhuangtai[i]]==0){\n        \t\t\t\tdp[j | mzhuangtai[i]]=dp[j]+dp[mzhuangtai[i]];\n        \t\t\t}else{\n        \t\t\t\tdp[j | mzhuangtai[i]]=Math.min(dp[j | mzhuangtai[i]], dp[j]+dp[mzhuangtai[i]]);\n        \t\t\t}\n        \t\t}\n        \t}\n        }\n        System.out.println(dp[(1<<m)-1]==0?-1:dp[(1<<m)-1]);\n    }\n}\n\n E 正文"},{"aid":"82790","title":"状压dp-糖果（c++）","date":"2022-01-18","likes":0,"views":1096,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-糖果\n\n Server-side output Markdown text\n```cpp\n#include<iostream>\n#include<string.h>\nusing namespace std;\nint dp[1<<20];\nint sweet[105];\nint main(){\n    int n,m,k;\n    cin>>n>>m>>k;\n    int total=(1<<m)-1;\n    memset(dp,-1,sizeof(dp));\n    for(int i=1;i<=n;i++){\n        int x;\n        int temp=0;\n        for(int j=1;j<=k;j++){\n            cin>>x;\n            temp=temp|(1<<x-1);\n        }\n        sweet[i]=temp;\n        dp[temp]=1;\n    }\n    for(int i=0;i<=total;i++){\n        if(dp[i]!=-1){\n            for(int j=1;j<=n;j++){\n                int tmp=sweet[j];\n                if(dp[tmp|i]==-1||dp[tmp|i]>dp[i]+1){\n                    dp[tmp|i]=dp[i]+1;\n                }\n            }\n        }\n    }\n    cout<<dp[total]<<endl;\n    return 0;\n}\n```\n\n E 正文"},{"aid":"82497","title":"蓝桥杯2019年第十届省赛真题-糖果","date":"2022-01-09","likes":0,"views":983,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-糖果\n\n解题思路:\nIDA*优化暴搜\n其实IDA* 是由两部分组成，迭代加深＋估价函数。\n迭代加深　其实就是在我们深搜的时候，为了防止DFS在一个错误的方向上一直延伸向下查找，而设立每一次搜索对搜索层数的限制，如果答案在更深层，则depth＋＋\n估价函数　其实就是我们在深搜时进行的一个可行性剪枝，在这个题目里我们是进行对目标的预估，比如总的层数有５层，如果我们现在搜索到了第三层，现在预估函数给出我们至少还需要３层,则总的层数＜现在所在的层数　＋还剩的层数，则退出。\n\n代码里面还有一些细节操作来说明一下，在一个每一行中，我们可以用０１来表示有没有糖果，所以我们可以利用二进制来存储，数据范围ｍ＜20，所以用int储存１＜＜ｍ是完全足够的。同时在搜索的时候，可以用lowbit取得最低位的１来优化。而且搜索过程中，我们可以找每列中最少的那一行，比如在案例中，４只有一行出现过，那么它就是必选的，而１在很多行都出现，所以我们的策略直接从最少的开始查找，进一步优化速度。\n\n参考代码:\n\n#include<bits/stdc++.h>\nusing namespace std;\nconst int N = 110, M = 1 << 20;\nvector<int> col[N];\nint Log2[M];\nint n,m,k;\nint lowbit(int x){return x & -x;}       //返回最低位的1所对应的值\nbool h(int state)                           //可行性剪枝 /估价函数\n{\n    int res = 0;\n    for(int i = (1 << m) - 1 - state;i;i -= lowbit(i))\n    {\n        int c = Log2[lowbit(i)];\n        res ++ ;\n        for(auto row : col[c]){\n            i &= ~row;                                    //因为i是反的，所以得先将row取反\n        }\n    }\n    return res;\n}\nbool dfs(int depth,int state)\n{\n    if(!depth || h(state) > depth) return state == (1 << m) - 1;         //如果层数搜完了，或者剪枝不够在继续 则返回状态stare\n\n    // 找到选择性最少的一列\n    int t = -1;\n    for(int i = (1 << m) - 1 - state; i;i -= lowbit(i))            //i这里将原本为 表示1作为有糖果，转化为0有糖果，这样可以让lowbit查找优化\n    {\n        int c = Log2[lowbit(i)];\n        if(t == -1 || col[t].size() > col[c].size() )\n        {\n            t = c;\n        }\n    }\n\n    for(auto row : col[t])                                 //搜索下一层\n    {\n        if(dfs(depth - 1,state | row)){\n            return true;\n        }\n    }\n    return false;\n}\nint main()\n{\n    cin >> n >> m >> k;\n    for(int i = 0; i < m; i ++ ) Log2[1 << i] = i;\n    for(int i = 0 ;i < n ;i ++ )\n    {\n        int state = 0;\n        for(int j = 0; j < k ; j ++ )\n        {\n            int c;\n            cin >> c;\n            state |= 1 << c - 1;\n        }\n        for(int j = 0 ;j < m ; j ++ )\n            if(state >> j & 1)\n            {\n                col[j].push_back(state);\n            }\n\n    }\n    int depth = 0;\n    while(depth <= m && !dfs(depth,0)) depth ++ ; //IDA*迭代加深  搜索一层情况，不够在慢慢扩散\n\n    if (depth > m) depth = -1;\n    cout<<depth<<endl;\n    return 0;\n}\n\n E 正文"}],"2304":[{"aid":"107094","title":"string的find函数 #2304: 蓝桥杯2019年第十届省赛真题-特别数的和","date":"2024-11-12","likes":0,"views":458,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-特别数的和\n\n Server-side output Markdown text\n```\n#define _CRT_SECURE_NO_WARNINGS 1\n#include<algorithm>\n#include<iostream>\n#include<sstream>\n#include<cstring>\n#include<cstdio>\n#include<string>\n#include<vector>\n#include<stack>\n#include<queue>\n#include<map>\n#include<set>\n\n#define MAX 0x3f3f3f3f\n#define MIN -0x3f3f3f3f\n\nusing namespace std;\n\ntypedef long long ll;\n\nint main() {\n\tint n;\n\tcin >> n;\n\n\tint res = 0;\n\tfor (int i = 1; i <= n; i++) {\n\t\tstring s = to_string(i);\n\t\tif (s.find('0') !=string::npos || s.find('1') != string::npos || s.find('2') != string::npos || s.find('9') != string::npos) {\n\t\t\tres += i;\n\t\t}\n\t}\n\n\tcout << res;\n\n\treturn 0;\n}\n```\n\n E 正文"},{"aid":"103231","title":"蓝桥杯2019年第十届省赛真题-特别数的和","date":"2024-03-10","likes":0,"views":720,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-特别数的和\n\n#include <iostream>\n#include <cstring>\n#include <cstdio>\n#include <algorithm>\n\nusing namespace std;\nusing ll=long long;\nint res;\nbool check(int n)\n{\n  int x=n;\n  while(x>0)\n  {\n    int y=x%10;\n    if(y==2||y==0||y==1||y==9)\n    {\n      return true;\n    }\n    else x/=10;\n  }\n  return false;\n}\n\nint main()\n{\n  int n;cin>>n;\n  for(int i=1;i<=n;i++)\n  {\n    if(check(i))res+=i;\n  }\n  cout<<res;\n  return 0;\n}\n\n E 正文"},{"aid":"100477","title":"练练用vector容器解题","date":"2023-12-02","likes":0,"views":503,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-特别数的和\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<bits/stdc++.h>\n#include<vector>\nusing namespace std;\nconst int N=10010;\nint n,sum=0;\nvector<int> v;\n\nint main(){\n    cin>>n;\n    for(int i=1;i<=n;i++){\n        int k=i;\n        while(k){\n            int t=k%10;\n            k=k/10;\n            if(t==2||t==0||t==1||t==9){\n                v.push_back(i);\n                break;\n            }\n        }\n    }\n    for(int i=0;i<v.size();i++){\n        sum+=v[i];\n    }\n    cout<<sum<<endl;\n    return 0;\n}\n\n E 正文"},{"aid":"95636","title":"蓝桥杯2019年第十届省赛真题-特别数的和","date":"2023-04-05","likes":0,"views":582,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-特别数的和\n\n解题思路:\n\n注意事项:\n\n参考代码:\nn = int(input())\ns = 0\nfor i in range(1,n+1):\n    for j in str(i):\n        if j in '2019':\n            s+=i\n            break\nprint(s)\n\n E 正文"},{"aid":"95573","title":"纯签到题,str.count直接秒了","date":"2023-04-03","likes":0,"views":585,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-特别数的和\n\n解题思路:\n\n注意事项:\n\n参考代码:\nn=int(input())\ncnt=0\nfor i in range(1,n+1):\n    t=str(i)\n    if t.count('2')>0 or t.count('0')>0 or t.count('1')>0 or t.count('9')>0:\n        cnt+=i\nprint(cnt)\n\n E 正文"}],"2305":[{"aid":"102390","title":"等差数列最小项问题 直观法求解","date":"2024-02-01","likes":0,"views":691,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-等差数列\n\n解题思路:求出公差后运用公式求解\n\n注意事项:注意公差为0 情况，直接输出n\n\n参考代码:\n#include <iostream>\n#include <cstring>\n#include <vector>\n#include <algorithm>\n#include <cmath>\n#include <iomanip>\n#include <string>\nusing namespace std;\nint a[100001];\nint main()\n{\n    int n,i;\n    cin>>n;\n    for(i=0;i<n;i++)\n    {\n        cin>>a[i];\n    }\n    sort(a,a+n);//排序\n     int minn=100000009;\n    for(i=0;i<=n-2;i++)\n    {\n         minn=min(minn,a[i+1]-a[i]);//求出公差\n\n    }\n     if(minn > 0 && (a[n-1] - a[0])%minn == 0)//特判\n      cout<<(a[n-1]-a[0])/minn+1;//注意公差为0情况\n      else\n      cout<<n;\n     return 0;\n}\n\n E 正文"},{"aid":"102187","title":"找到各差的最大公约数，从而就OK了，就是真正的差","date":"2024-01-23","likes":0,"views":601,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-等差数列\n\n解题思路:\n\n注意事项:\n\n参考代码:\nimport java.util.Arrays;\nimport java.util.Scanner;\n\n/**\n * 数学老师给小明出了一道等差数列求和的题目。但是粗心的小明忘记了一 部分的数列，只记得其中 N 个整数。\n * 现在给出这 N 个整数，小明想知道包含这 N 个整数的最短的等差数列有几项?\n */\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] arr= new int[n];\n        for (int i = 0; i < n; i++) {\n            arr[i] = sc.nextInt();\n        }\n        Arrays.sort(arr); // 排序\n        // 求各差的最大公约数即可\n        int[] diff = new int[n - 1];\n        for (int i = 0; i < n - 1; i++) {\n            diff[i] = arr[i + 1] - arr[i];\n        }\n        if (arr[0] == arr[n - 1]){\n            System.out.println(n);\n            return;\n        }\n        int temp = 0;\n        for (int i = 0; i < n - 2; i++) {\n            temp = gcd(diff[i], diff[i + 1]);\n            diff[i + 1] = temp;\n        }\n        System.out.println((arr[n-1] - arr[0]) / temp + 1);\n\n    }\n    public static int gcd(int a, int b){\n        return b == 0 ? a : gcd(b, a % b);\n    }\n}\n\n E 正文"},{"aid":"96956","title":"蓝桥杯2019年第十届省赛真题-等差数列","date":"2023-06-15","likes":0,"views":755,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-等差数列\n\n解题思路:将n个数排序后找到他们的相邻数之间的差，然后在找公差之间的最大公约数，这个数就是公差\n\n注意事项:题目中有一个公差为0的答案所以要特判一下\n\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\nint gcd (int a,int b)\n{\n\treturn b>0 ? gcd(b,a%b):a;\n}\nint main()\n{\n\tint n;\n\tscanf(\"%d\",&n);\n\tint x[n+5];\n\tint y[n+5];\n\tmemset(y,0,sizeof(y));\n\tmemset(x,0,sizeof(x));\n\tfor(int i=0;i<n;i++)\n\t{\n\t\tscanf(\"%d\",&x[i]);\n\t}\n\tsort(x,x+n);\n\tfor(int i=0;i<n-1;i++)\n\t{\n\t\ty[i]=x[i+1]-x[i];\n\t}\n\tsort(y,y+n);\n\tint a=y[0];\n\tfor(int i=1;i<n-1;i++)\n\t{\n\t\ta=gcd(a,y[i]);\n\t}\n\tif(a==0)\n\t{\n\t\tprintf(\"%d\",n);\n\t\treturn 0;\n\t}\n\tint ans=x[n-1]-x[0];\n\tprintf(\"%d\",ans/a+1);\n\treturn 0;\n}\n\n E 正文"},{"aid":"95637","title":"蓝桥杯2019年第十届省赛真题-等差数列","date":"2023-04-05","likes":0,"views":513,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-等差数列\n\n解题思路:\n\n注意事项:\n\n参考代码:\nn = int(input())\nL = list(map(int,input().split()))\nL.sort()\nL1 = []\nfor i in range(len(L)-1):\n    L1.append(L[i+1]-L[i])\nif 0 in L1:\n    print(n)\nelse:\n    a = min(L1)\n    print(1+((L[-1]-L[0])//a))\n\n E 正文"},{"aid":"95269","title":"找最大公约数也是最小的公差","date":"2023-03-25","likes":0,"views":630,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-等差数列\n\n解题思路:因为是从等差数列取的几个数，所以这几个数一定是公差的几倍或者就是公差，为了满足n个数都能匹配，所以我们要选择最小公差\n\n注意事项:\n\n参考代码:\nn=int(input())\na=list(map(int,input().split()))\na.sort()\nd=[]\nfor i in range(1,len(a)):\n    d.append(a[i]-a[i-1])\nif 0 in d:\n    print(n)\nelse:\n    b=min(d)\n    cnt=(a[-1]-a[0])//b+1\n    print(cnt)\n\n E 正文"}],"2306":[{"aid":"94588","title":"后缀表达式公式","date":"2023-03-06","likes":0,"views":747,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-后缀表达式\n\n Server-side output Markdown text\n\n重点是符号个数不为0时，求后缀表达式最大结果公式：max(0)-min(n+m-1) + abs() + ..... abs(a1)+abs(a2)+abs().....\n```\nimport java.util.*;\npublic class Main {\n    public static void main(String[] args) {\n    \tScanner sc = new Scanner(System.in);\n    \tint n = sc.nextInt();\n    \tint m = sc.nextInt();\n    \tint[] arr = new int[n+m+1];\n    \tfor(int i = 0; i<n+m+1; i++) {\n    \t\tarr[i] = sc.nextInt();\n    \t}\n    \tlong sum = 0;\n    \tArrays.sort(arr);\n//    \tSystem.out.print(Arrays.toString(arr));\n    \tif(m == 0) {\n    \t\tfor(int i = 0; i<n+m+1; i++) {\n    \t\t\tsum += arr[i];\n    \t\t}\n    \t}else {\n    \t\tsum = arr[n+m] - arr[0];\n    \t\tfor(int i = 1; i<n+m; i++) {\n    \t\t\tsum+= Math.abs(arr[i]);\n    \t\t}\n    \t}\n    \tSystem.out.print(sum);\n    }\n}\n```\n\n E 正文"},{"aid":"92957","title":"蓝桥杯2019后缀表达式：Java版","date":"2023-01-08","likes":0,"views":681,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-后缀表达式\n\n Server-side output Markdown text\n```java\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int n = scanner.nextInt();\n        int m = scanner.nextInt();\n        long ans = 0;\n        int[] arr = new int[n+m+1];\n        for (int i = 0; i < n + m + 1; i++) {\n            arr[i] = scanner.nextInt();\n        }\n        if ( m == 0) {\n            for (Integer i : arr) {\n                ans += i;\n            }\n        } else {\n            Arrays.sort(arr);    // 升序排序\n            ans = arr[n+m] - arr[0];\n            for (int i = 1; i < n+m; i++) {\n                ans += Math.abs(arr[i]);\n            }\n        }\n        System.out.println(ans);\n    }\n}\n```\n\n E 正文"},{"aid":"92894","title":"思维题-只需考虑三种情况 超级简单且明了！","date":"2023-01-06","likes":0,"views":633,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-后缀表达式\n\n解题思路:\n\n\"\"\"\n没有负号：\n        答案就是所有数的和\n有负号：\n        只要正数和负数搭配答案就是所有的数绝对值的和\n        纯正数和纯负数分开考虑\n\"\"\"\n\n注意事项:\n\"\"\"\n0可以构造正负数\n\"\"\"\n#参考代码如下：\ndata=list(map(int,input().split()))\nn,m=data[0],data[1]\nlist1=list(map(int,input().split()))\nif m==0:# 都为加号\n    print(sum(list1))\nelse:\n    list2,list3=[],[] # 分别提取出正数，负数\n    for i in list1:\n       list2.append(i)  if i>0 else list3.append(i) # 一个简单的三目运算符\n    # 正序排序\n\n    list2.sort()\n    list3.sort()\n\n    if 0 in list1 or len(list2)>0 and len(list3)>0  : # 正负数搭配(0可以构造)\n        print(sum(list2)-sum(list3))\n    elif len(list2)==0: # 全负数\n        print(list3[-1]-sum(list3[:-1])) # 保证最大数减去其他数的和\n    elif len(list3)==0: # 全正数\n        print(sum(list2[1:])-list2[0]) # 先产生负数 然后负数减去正数 最后再用一个正数去减负数->推导得到：除去最小的数的和-最小的数\n\n E 正文"},{"aid":"86260","title":"不知道自己哪里错了进来","date":"2022-04-05","likes":0,"views":1295,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-后缀表达式\n\n解题思路:\n很多人提交这题都错了，相信还不知道为什么，大部分人是排序后减小的，加大的；\n\n错就除了如果只要有一个负号，负数也可以全部变成正数然后相加的，不理解看接下来我举得例子\n\n2 2\n\n-1 -2 -3 -4 - 5\n\n我们可以写成-1-（（-2）+（-3）+（-4））-（-5）\n\n是不是只要一个负号就可以得除最大值，懂了没有；如果按大部分人的思路的话，这题\n\n会这么运算-1-（-5）-（-4）+（-2）+（-3）；\n\n所以这题解分为两种情况，\n\n1.无负号，就把输入的数全加起来\n\n2.有负号\n\n除了上述说的，还有一种情况，即使都数字大部分都是正数，但是因为负负得正，两个负号也可以变成正号，奇数个负号只用减一次即可，：有加号有负号，无论你怎么输入，我们都可以拿最大值减去最小值然后加上剩下数的绝对值即可，为什么呢？负负得正是关键点\n\n细看点击链接     http://t.csdn.cn/oDhUB\n参考代码:\n\n#includeusing namespace std;\n#define ll long long\nint a[200009];\n\nint main()\n{\n\tint n, m; cin >> n >> m;\n\tint N = n + m + 1;\n\tll sum = 0;\n\tfor (int i = 0; i < N; i++)\n\t\tcin >> a[i];\n\t//当没有减号的时候直接相加\n\tif (m == 0)\n\t{\n\t\tfor (int i = 0; i < n + m + 1; i++)\n\t\t{\n\t\t\tsum += a[i];\n\t\t}\n\t}\n\telse\n\t{\n\t\tsort(a, a + N);\n\t\tsum = a[N - 1] - a[0];\n\t\tfor (int i = 1; i < N - 1; i++)\n\t\t\tsum += abs(a[i]);\n\t}cout << sum << endl;\n\treturn 0;\n}\n\n E 正文"},{"aid":"85508","title":"蓝桥杯2019年第十届省赛真题-后缀表达式（Python）","date":"2022-03-20","likes":0,"views":1037,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-后缀表达式\n\n解题思路:参考前面的题解\n\n注意事项:\n\n参考代码:\nn,m = map(int,input().split())\ns = list(map(int,input().split()))\ns.sort()\ndef solve(n,m):\n    if m==0:\n        return sum(s)\n    ans = sum([abs(i) for i in s])\n    if s[0]>0:\n        return ans - 2*s[0]\n    if s[-1]<0:\n        return ans + 2*s[-1]\n    return ans\nprint(solve(n,m))\n\n E 正文"}],"2307":[{"aid":"72539","title":"蓝桥杯2019年第十届真题-灵能传输-题解（Java代码）","date":"2020-09-08","likes":0,"views":1703,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-灵能传输\n\n Server-side output Markdown text\n```c\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.util.Arrays;\n//import java.util.Scanner;\n\npublic class Main {\n\tprivate static long[] a;\n\tprivate static long[] s;\n\tprivate static boolean[] st;\n\tprivate static int n;\n\tpublic static void main(String[] args) throws NumberFormatException, IOException {\n\t\tint T;\n\t\t//Scanner sc = new Scanner(System.in);\n\t\tBufferedReader sc = new BufferedReader(new InputStreamReader(System.in));\n\t\t//T = sc.nextInt();\n\t\tT = Integer.parseInt(sc.readLine().trim());\n\t\twhile(T-- > 0) {\n\t\t\t//n = sc.nextInt();\n\t\t\tn = Integer.parseInt(sc.readLine().trim());\n\t\t\tString[] arr = sc.readLine().trim().split(\" \");\n\t\t\ta = new long[n + 1];\n\t\t\ts = new long[n + 1];\n\t\t\tst = new boolean[n + 1];\n\t\t\ts[0] = 0;\n\t\t\tfor(int i = 1; i <= n; i++) {\n\t\t\t\t//s[i] = sc.nextLong();\n\t\t\t\ts[i] = Integer.parseInt(arr[i - 1]);\n\t\t\t\ts[i] += s[i - 1];\n\t\t\t}\n\t\t\tlong s0 = s[0], sn = s[n];\n\t\t\tif(s0 > sn) {\n\t\t\t\tlong temp = s0;\n\t\t\t\ts0 = sn;\n\t\t\t\tsn = temp;\n\t\t\t}\n\t\t\tArrays.sort(s);\n\n\t\t\tfor(int i = 0; i <= n; i++) {\n\t\t\t\tif(s[i] == s0) {\n\t\t\t\t\ts0 = i;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\tfor (int i = n; i >= 0; i--) {\n\t\t\t\tif(s[i] == sn) {\n\t\t\t\t\tsn = i;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\n\t\t\tint l = 0, r = n;\n\t\t\tfor(int i = (int)s0; i >= 0; i -= 2) {\n\t\t\t\ta[l++] = s[i];\n\t\t\t\tst[i] = true;\n\t\t\t}\n\t\t\tfor(int i = (int)sn; i <= n; i += 2) {\n\t\t\t\ta[r--] = s[i];\n\t\t\t\tst[i] = true;\n\t\t\t}\n\t\t\tfor(int i = 0; i <= n; i++) {\n\t\t\t\tif(!st[i]) {\n\t\t\t\t\ta[l++] = s[i];\n\t\t\t\t}\n\t\t\t}\n\n\t\t\tlong res = 0;\n\n\t\t\tfor(int i = 1; i <= n; i++) {\n\t\t\t\tif(Math.abs(a[i] - a[i - 1]) > res) {\n\t\t\t\t\tres = Math.abs(a[i] - a[i - 1]);\n\t\t\t\t}\n\t\t\t}\n\n\t\t\tSystem.out.println(res);\n\t\t}\n\t}\n}\n```\n\n E 正文"},{"aid":"72153","title":"蓝桥杯2019年第十届真题-灵能传输-题解（C++代码）","date":"2020-08-18","likes":0,"views":2853,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-灵能传输\n\n解题思路:直接在a[i]上操作，没有好的解决办法，考虑一下前缀和，发现问题就转换成了：给定一个序列，重新排列元素顺序，要求s0,sn的位置不能变即固定起点终点 ，使得该序列的相邻两数之差的绝对值最小。 可以证明当该序列单调时，有相邻两数的差值的绝对值最小。\n注意事项:\n具体思路见：灵能传输 思路解析\n\n#include<bits/stdc++.h>\nusing namespace std;\n#define ll long long\nconst int N=3e5+3;\nll a[N],s[N];\nbool vis[N];\nint n;\nint main(){\n\tint T;\n\tscanf(\"%d\",&T);\n\twhile(T--){\n\t\tmemset(vis,0,sizeof(vis));\n\t\tscanf(\"%d\",&n);\n\t\ts[0]=0;\n\t\tfor(int i=1;i<=n;++i){\n\t\t\tscanf(\"%lld\",&s[i]);\n\t\t\ts[i]+=s[i-1];\n\t\t}\n\t\tll s0=0,sn=s[n];\n\t\tif(s0>sn) swap(s0,sn);//前小后大，为方便取数，可避免讨论取数时重复取的问题。\n\t\tsort(s,s+n+1);\n\t\tint l=0,r=n;\n\t\tfor(int i=lower_bound(s,s+n+1,s0)-s;i>=0;i-=2){\n\t\t\ta[l++]=s[i],vis[i]=1;\n\t\t}\n\t\tfor(int i=lower_bound(s,s+n+1,sn)-s;i<=n;i+=2){\n\t\t\ta[r--]=s[i],vis[i]=1;\n\t\t}\n\t\tfor(int i=0;i<=n;++i){\n\t\t\tif(!vis[i]) a[l++]=s[i];\n\t\t}\n\t\tll res=0;\n\t\tfor(int i=1;i<=n;++i)\n\t\t\tres=max(res,abs(a[i]-a[i-1]));\n\t\tprintf(\"%lld\\n\",res);\n\t}\n\treturn 0;\n}\n\n E 正文"}],"2308":[{"aid":"102755","title":"蓝桥杯2019年第十届省赛真题-旋转(Java)","date":"2024-02-18","likes":0,"views":566,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-旋转\n\n Server-side output Markdown text\n```java\nimport java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int m = sc.nextInt();\n        int[][] arr = new int[n][m];\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < m; j++) {\n                arr[i][j] = sc.nextInt();\n            }\n        }\n        int[][] arrNew = new int[m][n];\n        for (int i = 0; i < arrNew.length; i++) {\n            for (int j = 0; j < arrNew[i].length; j++) {\n                arrNew[i][j] = arr[arr.length-1-j][i];\n            }\n        }\n        for (int[] ints : arrNew) {\n            for (int anInt : ints) {\n                System.out.print(anInt+\" \");\n            }\n            System.out.println();\n        }\n    }\n}\n```\n\n E 正文"},{"aid":"95640","title":"蓝桥杯2019年第十届省赛真题-旋转","date":"2023-04-05","likes":0,"views":548,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-旋转\n\n解题思路:\n\n注意事项:\n\n参考代码:\nm,n = map(int,input().split())\nL = [list(map(int,input().split()))for i in range(m)]\nL1 = []\nL2 = []\nfor i in range(n):\n    for j in range(m):\n        L1.append(L[j][i])\nfor i in range(n):\n    while len(L1)>0:\n        L2.append(L1[:m][::-1])\n        L1 = L1[m:]\nfor i in L2:\n    for j in i:\n        print(j,end=\" \")\n    print()\n\n E 正文"},{"aid":"78563","title":"平凡の解法","date":"2021-04-14","likes":0,"views":838,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-旋转\n\n解题思路:就是用迭代的方法将所有的数组读入，然后再构建一个反转的数组，最后再读入这个相反的顺序，所以基本，就是的很容易的，中规中矩的题，可能会有达大佬想到新解法，但估计很难。时间复杂度O(n^2),空间复杂度O(n^2)\n\n注意事项:注意这个问题的翻转方向，我第一次差一点的翻车了，还好在调试的时候注意到了。\n\n参考代码:\nm,n = map(int,input().split())\nnum = [0 for row in range(m)]\nfor i in range(m):\n   num[i] = list(map(int,input().split()))\nans = [[0 for i in range(m)] for j in range(n)]\nfor i in range(n):\n   for j in range(m):\n       ans[i][j] = num[m - 1 - j][i]\nfor i in range(n):\n   for j in range(m):\n       print(ans[i][j],end=\" \")\n   print()\n\n E 正文"},{"aid":"78472","title":"蓝桥杯2019年第十届真题-旋转-题解(C++代码)","date":"2021-04-11","likes":0,"views":647,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-旋转\n\n解题思路: 寻找旋转下标的对应关系\n\n注意事项:\n\n参考代码:\n#include <iostream>\nusing namespace std;\n\nint main(int argc, char** argv) {\n\tint n, m;\n\tcin >> n >> m;\n\tint data[n][m];\n\tfor(int i = 0; i < n; i++){\n\t\tfor(int j = 0; j < m; j++){\n\t\t\tcin >> data[i][j];\n\t\t}\n\t}\n\tint rot[m][n];\n\tfor(int i = 0; i < m; i++){\n\t\tfor(int j = 0; j < n; j++){\n\t\t\trot[i][j] = data[n-1-j][i];\n\t\t\tcout << rot[i][j] << \" \";\n\t\t}\n\t\tcout << endl;\n\t}\n\n\treturn 0;\n}\n\n E 正文"},{"aid":"78157","title":"2308: 蓝桥杯2019年第十届真题-旋转","date":"2021-04-01","likes":0,"views":832,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-旋转\n\n解题思路:\n一个简单的列表运用\n注意事项:\n如果能运用矩阵会更简单\n参考代码:\na,b=map(int,input().split())\nlist1=[[0]*b for i in range(a)]\nlist2=[[0]*a for i in range(b)]\nfor i in range(a):\n    list1[i]=list(map(int,input().split()))\n    for j in range(b):\n        list2[j][a-1-i]=list1[i][j]\nfor i in range(b):\n    for j in range(a):\n        print(list2[i][j],end=' ')\n    print()\n\n E 正文"}],"2309":[{"aid":"86382","title":"蓝桥杯2019年第十届省赛真题-人物相关性分析（滑动窗口）","date":"2022-04-06","likes":0,"views":952,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-人物相关性分析\n\n Server-side output Markdown text\n```C++\n#include<iostream>\n#include<cstdlib>\n#include<string>\n\n/*\n\t注意！如果你只拿了91分，那么很可能是你没开longlong!!!\n\n\t思路：预处理得到a[i]、b[i]两个数组分别表示当前位置是否存在Alice、Bob\n\n\t然后对于每个alice，我们先求一边她左边区域k内Bob的数量，再求一遍右边的数量，加起来就得到我们要的结果。\n\t动态维护区域k，很明显我们可以使用滑动窗口，以求左边区域为例:\n\t[l,r]维护正确区间，cnt为区间内bob的数量，这里有一个小细节，缩l的条件是：r - l + 1 > k + 4，如果不懂可以参考k=1时，\"Alice Bob\"与\"Alice  Bob\"时，ans的值。\n*/\nconst int MAXN = 1e6 + 9;\nint n, k;\nlong long ans; // 必须开！！！\nstd::string t, s;\nchar ch;\nbool a[MAXN], b[MAXN];\n\nint main(){\n\tstd::ios::sync_with_stdio(false);\n\tstd::cin.tie(0);\n\tstd::cout.tie(0);\n\tstd::getline(std::cin, t);\n\tstd::getline(std::cin, s);\n\tk = stoi(t);\n\tn = s.size();\n\n    for(int i = 0; i < n; i++){\n        if(s[i] == 'A' && i + 4 < n && s.substr(i, 5) == \"Alice\" ){\n            a[i] = true;\n        }\n        if(s[i] == 'B' && i + 2 < n && s.substr(i, 3) == \"Bob\"){\n            b[i] = true;\n        }\n    }\n\n    for(int r = 0, l = 0, cnt = 0; r < n; r++){\n        if(b[r]) cnt++;\n        while(r - l + 1 > k + 4){\n            if(b[l]) cnt--;\n            l++;\n        }\n        if(a[r]) ans += cnt;\n    }\n    for(int l = n-1, r = n-1, cnt = 0; l >= 0; l--){\n        if(b[l]) cnt++;\n        while(r - l + 1 > k + 6){\n            if(b[r]) cnt--;\n            r--;\n        }\n        if(a[l]) ans += cnt;\n    }\n\n\tstd::cout << ans;\n\treturn 0;\n}\n```\n\n E 正文"},{"aid":"85328","title":"题解 2309: 蓝桥杯2019年第十届省赛真题-人物相关性分析-滑动窗口算法","date":"2022-03-16","likes":0,"views":1315,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-人物相关性分析\n\n解题思路:\n\n常规思想：两个不定长数组，j下标从0开始Alice找Bob，时间超限55\n\nBob运用数组方法：数组下标差的到的中间那段，找Bob为1的index有几个，然后相加，时间超限82\n\n滑动窗口算法思想优化算法：循环Alice时候，下一次的Alice寻找Bob的开始和结束位置是上一次Alice的寻找Bob的开始和结束位置。\n\n注意事项:sc.nextInt()和sc.nextLine()的结合使用时需要吞掉一个换行符。\n\n参考代码:\n\nimport java.util.ArrayList;\nimport java.util.Arrays;\nimport java.util.Scanner;\npublic class Main {\n\tpublic static void main(String[] args) {\n\t\tScanner sc=new Scanner(System.in);\n\t\tint k=sc.nextInt();String kong=sc.nextLine();\n\t\tlong count=0;\n\t\tString str=sc.nextLine();\n\t\tArrayList<Integer> alice=new ArrayList<Integer>();\n\t\tArrayList<Integer> bob=new ArrayList<Integer>();\n\t\t//int[] bob=new int[1000000];\n\t\tint froma=0,fromb=0;\n\t\twhile(true){\n\t\t\tint indexa=str.indexOf(\"Alice\",froma);\n\t\t\tfroma=indexa+4;\n\t\t\tif(indexa==-1){froma=str.length()-1;}\n\t\t\tint indexb=str.indexOf(\"Bob\",fromb);\n\t\t\tfromb=indexb+2;\n\t\t\tif(indexb==-1){fromb=str.length()-1;}\n\t\t\tif(indexa==-1&&indexb==-1){\n\t\t\t\tbreak;\n\t\t\t}\n\t\t\tif(indexa!=-1&&indexa+4<=str.length()-1){\n\t\t\t\tif((indexa+5==str.length()&&feizimu(str.charAt(indexa-1)))||(indexa==0&&feizimu(str.charAt(indexa+5)))||(feizimu(str.charAt(indexa-1))&&feizimu(str.charAt(indexa+5)))){\n\t\t\t\t\talice.add(indexa);\n\t\t\t\t}\n\t\t\t}\n\n\t\t\tif(indexb!=-1&&indexb+2<=str.length()-1){\n\t\t\t\tif((indexb+3==str.length()&&feizimu(str.charAt(indexb-1)))||(indexb==0&&feizimu(str.charAt(indexb+3)))||(feizimu(str.charAt(indexb-1))&&feizimu(str.charAt(indexb+3)))){\n\t\t\t\t\tbob.add(indexb);\n\t\t\t\t\t//bob[indexb]++;\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\t//int As = alice.size(), Bs = bob.size();       //As与Bs分别为两数组元素个数\n\t    //int bl = 0, br = 0;\n\t\tint j=0,m=0;\n\t\tfor(int i=0;i<alice.size();i++){\n\t\t\t/*int j=alice.get(i)-k-3;\n\t\t\tif(j<0){\n\t\t\t\tj=0;\n\t\t\t}\n\t\t\tint m=alice.get(i)+k+5;\n\t\t\tif(m>=str.length()){\n\t\t\t\tm=str.length()-1;            //此方法（Alice找Bob，Bob位置用下标定义）时间超限82\n\t\t\t}\n\t\t\tfor(;j<=m;j++){\n\t\t\t\tif(bob[j]!=0){\n\t\t\t\t\tcount++;\n\t\t\t\t}\n\t\t\t}*/\n\n\t\t\t/*while(bl < Bs && bob.get(bl)< alice.get(i) - k - 3)    bl++;   //维护窗口左边界\n\t        while(br < Bs && bob.get(br) <= alice.get(i) + k + 5)   br++;   //维护窗口右边界\n\t        count += br - bl;    */                     //下一次Alice的j和m都是从上一次的j和m开始，ac通过\n\n\t\t\t/*for(int j=0;j<bob.size();j++){\n\t\t\t\tif(bob.get(j)<alice.get(i)&&alice.get(i)-bob.get(j)<=k+3){\n\t\t\t\t\tcount++;\n\t\t\t\t}\n\t\t\t\tif(bob.get(j)>alice.get(i)&&bob.get(j)-alice.get(i)<=k+5){\n\t\t\t\t\tcount++;                       //j每次从0开始，时间超限82\n\t\t\t\t}\n\t\t\t\tif(bob.get(j)-alice.get(i)>k+5){\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}*/\n\n\t\t\tfor(;j<bob.size();j++){\n\t\t\t\tif(alice.get(i)-bob.get(j)<=k+3){\n\t\t\t\t\tbreak;\n\t\t\t\t}                           //下一次Alice的j和m都是从上一次的j和m开始，ac通过\n\t\t\t\t                          // 使用滑动窗口的算法思想来优化算法，否则将超时。\n\t\t\t}\n\t\t\tfor(;m<bob.size();m++){\n\t\t\t\tif(bob.get(m)-alice.get(i)>k+5){\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t}\n\t\t\tcount+=m-j;\n\t\t}\n\t\tSystem.out.println(count);\n\n\t}\n\tpublic static boolean feizimu(char ch){\n\t\tif((ch>='a'&&ch<='z')||(ch>='A'&&ch<='Z')){\n\t\t\treturn false;\n\t\t}else{\n\t\t\treturn true;\n\t\t}\n\t}\n}\n\n E 正文"},{"aid":"84758","title":"二分法模块的使用，python","date":"2022-03-04","likes":0,"views":832,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-人物相关性分析\n\n Server-side output Markdown text\n# MarkDown编辑器基本使用说明\n\n**如果这是您第一次使用MarkDown编辑器，建议先阅读这篇文章了解一下Markdown的基本使用方法。**\n\n## 解题思路\n\n**1.找到所有Alice， Bob的下标，储存在一个列表里面\n2.通过遍历其中一个人的名字的下标，确定范围，在另一个人的列表里面确定数量\n**\n## 注意事项\n**1.通过首字母，切片看是不是Alice， Bob，判断名字前后有没有字母数字，没有才能放进列表，特殊的在句首，句尾\n2.范围的确定使用二分法可以快速的找到小于等于大范围的数的数量**\n## 插入代码\n\n\timport bisect\n\n\tk = int(input())\n\tm = str(input())\n\tA = []  # 储存Alice出现的位置\n\tB = []  # 储存Bob出现的位置\n\tq = [' ', '.', ',', '!', '?']\n\tfor i in range(len(m)):\n\t    if m[i] == 'A':\n\t        '''进行判断是不是Alice，是就添加下标'''\n\t        if (i == 0 and m[i:i + 5] == 'Alice' and m[i + 5] in q) or (i + 5 == len(m) and m[i:] == \"Alice\" and m[i - 1] in q):\n\t            A.append(i)\n\t            continue\n\t        if m[i:i + 5] == 'Alice' and m[i + 5] in q and m[i - 1] in q:\n\t            A.append(i)\n\t    elif m[i] == 'B':\n\t        '''判断是不是Bob，是就添加下标'''\n\t        if (i == 0 and m[i:i + 3] == 'Bob' and m[i + 3] in q) or (i + 3 == len(m) and m[i:] == \"Bob\" and m[i - 1] in q):\n\t            B.append(i)\n\t            continue\n\t        if m[i:i + 3] == 'Bob' and m[i + 3] in q and m[i - 1] in q:\n\t            B.append(i)\n\tt = 0  # 储存同时出现的次数\n\tfor i in A:\n\t    '''以Alice的下标遍历'''\n\t    a1 = i - (k + 3)  # 最小的范围下标\n\t    a2 = i + 5 + k + 1  # 最大的下标范围，再加1是为了后面二分法好找比这个数小的个数\n\t    if a1 < 0:\n\t        t += bisect.bisect_left(B, a2)  # 最小的范围小于零，所以组大范围的数量就是次数\n\t    else:\n\t        t += (bisect.bisect_left(B, a2) - bisect.bisect_left(B, a1))  # 最大的范围里的数 减去 最小的范围里的数 等于 次数\n\n\tprint(t)\n\n E 正文"},{"aid":"78378","title":"人物相关性分析C++","date":"2021-04-08","likes":0,"views":1092,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-人物相关性分析\n\n Server-side output Markdown text\n```cpp\n#include<iostream>\n#include<algorithm>\n#include<cstring>\n#include<vector>\nusing namespace std;\nstring str;\nint k;\nvector<int> a,b;\n//这个检查Alice和Bob是否符合要求是单独的单词\nbool check(char c){\n\treturn c>='A'&&c<='Z'||c>='a'&&c<='z';\n}\nint main(){\n\tcin>>k;\n\tgetchar();\n\tgetline(cin,str);\n\tfor(int i=0;i+5<=str.size();i++)\n\t\tif((!i || !check(str[i-1]))&&(i+5==str.size()|| !check(str[i+5])))\n\t\t\tif(str.substr(i,5)==\"Alice\")\ta.push_back(i);\n\n\tfor(int i=0;i+3<=str.size();i++)\n\t\t//用于检查独立单词是否符合题意，是上一个题解的补充\n\t\tif((!i || !check(str[i-1]))&&(i+3==str.size()|| !check(str[i+3])))\n\t\t\tif(str.substr(i,3)==\"Bob\")\tb.push_back(i);\n\n\tlong long ans=0;\n\t//下面的注释是参看y总的代码，分别找出Alice前面的Bob以及Bob前面的Alice\n\t//他们的和就是解\n//\tfor(int i=0,l=0,r=-1;i<a.size();i++)//Alice前面有多少个Bob\n//\t{\n//\t\twhile(r+1<b.size()&&a[i]>=b[r+1])\tr++;\n//\t\twhile(l<=r&&a[i]-1-(b[l+1]+3)+1>k)\tl++;\n//\t\tans+=r-l+1;\n//\t}\n//\tfor(int i=0,l=0,r=-1;i<b.size();i++)//Bob前面有多少个Alice\n//\t{\n//\t\twhile(r+1<a.size()&&b[i]>=a[r+1])\tr++;\n//\t\twhile(l<=r&&b[i]-1-(a[l+1]+5)+1>k)\tl++;\n//\t\tans+=r-l+1;\n//\t}\n\t//这个是参看了上一个题解替换了y总代码\n\tfor(int i = 0,l=0,r=0; i < a.size(); i++){  //遍历Alice数组元素\n        while(l < b.size() && b[l] <  a[i] - k - 3)    l++;   //维护窗口左边界\n        while(r < b.size() && b[r] <= a[i] + k + 5)   r++;   //维护窗口右边界\n        ans += r - l;             //答案加上窗口中元素个数\n    }\n\tcout<<ans;\n\treturn 0;\n}\n```\n\n E 正文"},{"aid":"77319","title":"2309: 蓝桥杯2019年第十届真题-人物相关性分析","date":"2021-03-10","likes":0,"views":1877,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-人物相关性分析\n\n解题思路:\n\n主要思想是滑动窗口\n用两个数组记录Alice和Bob出现时（首字母）的下标\n遍历Alice数组中的元素，在Bob数组中维护范围内的窗口\n范围为：Alice[i] - k - 3 <= Bob[ ] <= Alice[i] + k + 5   （3 和 5 分别为Bob和Alice的长度）\n每次循环让答案加上窗口长度即可(我代码中的 br 表示的是窗口右边界后一位，是为方便计算)\n细节请看代码\n\n参考代码:\n#include <bits/stdc++.h>\nusing namespace std;\n\nstring s;\t\t\t//定义全局变量s\n\nbool checkA(int i, int len){\t\t//判断是否为Alice, i为下标, len为字符串长度\n    if(len - i < 5)\treturn false;\n    return s[i+1] == 'l' && s[i+2] == 'i' && s[i+3] == 'c' && s[i+4] == 'e';\n}\n\nbool checkB(int i, int len){\t\t\t//判断是否为Bob, i为下标, len为字符串长度\n    if(len - i < 3)\treturn false;\n    return s[i+1] == 'o' && s[i+2] == 'b';\n}\n\nint main(){\n    int k;\t\t\t//定义k\n    cin >> k;\t\t//输入k\n    getchar();\t\t//吃回车\n\n    getline(cin, s);\t\t//整行输入字符串s\n    int len = s.length();\t//定义len为s的长度\n\n    vector<int> Alice, Bob;\t\t//定义数组记录名字出现时的下标\n\n    for(int i = 0; i < len; i++){\t\t\t//遍历字符串\n        if(s[i] == 'A' && checkA(i, len)){\t//如果字符为'A'判断是否为Alice\n            Alice.push_back(i);\t\t\t\t//添加下标到数组\n            i += 5;\t\t\t\t//跳过名字(名字后后空格,无需担心循环中的i++)\n        }\n        else if(s[i] == 'B' && checkB(i, len)){\t//如果字符为'B'判断是否为Bob\n            Bob.push_back(i);\t\t\t\t\t//添加下标到数组\n            i += 3;\t\t\t\t//跳过名字\n        }\n    }\n\n    int As = Alice.size(), Bs = Bob.size();\t\t//As与Bs分别为两数组元素个数\n    int bl = 0, br = 0;\t\t\t//bl与br分别为窗口左右边界\n\n    long long ans = 0;\t\t\t//定义答案（最后一个评测点会超过int范围）\n\n    for(int i = 0; i < As; i++){\t//遍历Alice数组元素\n    \twhile(bl < Bs && Bob[bl] < Alice[i] - k - 3)\tbl++;\t//维护窗口左边界\n    \twhile(br < Bs && Bob[br] <= Alice[i] + k + 5)\tbr++;\t//维护窗口右边界\n    \tans += br - bl;\t\t\t\t//答案加上窗口中元素个数\n\t}\n\n\tcout << ans << endl;\t\t//输出答案\n    return 0;\n}\n\n E 正文"}],"2310":[{"aid":"86420","title":"蓝桥杯2019年第十届省赛真题-扫地机器人(二分)","date":"2022-04-07","likes":0,"views":1214,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-扫地机器人\n\n Server-side output Markdown text\n```C++\n#include<iostream>\n#include<algorithm>\n\n/*\n\t思路：求最少时间，看数据范围，显然选择nlgn 以内的算法解决，而因为随着时间的增加，机器人能扫的范围也会对应的增加\n\t故这题可以选择二分处理，二分时间，显然l=2,r=n*2。注意！题目要求：机器人最后得回到原位！！！\n\t\t关于l、r边界：因为k<n，考虑最好的情况：k=n-1，那么x=2便可以完成任务\n\t\t\t\t\t\t\t\t\t最坏：k=1，那么k需要向左跑一次、向右跑一次，自然是2*n\n\t确定好边界后，我们真正的问题是：如何O(n)判断时间x内，所有机器人能否扫完1-n区间\n\n\t我们可以用贪心的思想，对所有机器人的位置排序使得:a1<a2<a3...<an，如果a1左边有地方需要扫描，我们肯定是选择让a1去扫描\n\t而不是a2、a3...,因为a1离他最近。因此，我们对每个ai，制定一个策略，用[p,n]表示需要扫描的区间\n\t\t1.如果p<ai，那么我们让ai去扫描[p,ai-1],因为要走回来，这个开销是（ai-p)*2。如果x连这个区间都扫不了\n\t\t，那么ai+1乃至以后肯定都扫不了这块区域，直接返回false。否则，我们假定ai已经走回原位，\n\t\t那么它需要尽可能向右贡献最大的价值，这个价值自然是a[i]+(x-(ai-p)*2)/2，于是p更新为这个价值+1\n\n\t\t2. 如果p>=ai,那么我们让ai用掉所有的步数向右扫：x/2, p可能比这个值还大！（实际上最多等于）\n\t\t我们取p与a[i]+x/2+1之间的max即可\n\n\t循环过程中只要p>n，那么返回true。注意p的定义！p=n时，代表[n,n]区间还需要扫描！\n\n\t分析结束，剩下是代码时间： （观察数据范围，以及大部分只使用+，故不需要开longlong）\n*/\nint n, m, a[100009];\nbool check(int x){\n\tint p = 1;\n\tfor(int i = 1; i <= m; i++){\n\t\tif(p < a[i]){\n\t\t\tint tot = (a[i] - p) * 2;\n\t\t\tif(x < tot) return false;\n\t\t\tp = a[i] + (x - tot) / 2 + 1;\n\t\t}else{\n\t\t\tp =  std::max(p, a[i] + x / 2 + 1);\n\t\t}\n\n\t\tif(p > n) return true;\n\t}\n\treturn false;\n}\n\nint main(){\n\tstd::cin >> n >> m;\n\tfor(int i = 1; i <= m; i++){\n\t\tstd::cin >> a[i];\n\t}\n\tif(n == m){\n\t\tstd::cout << 0 << std::endl;\n\t\treturn 0;\n\t}\n\tstd::sort(a+1, a+m+1);\n\tint l = 1, r = n * 2, mid;\n\twhile(l < r){\n\t\tmid = (r - l) / 2 + l;\n\t\tif(check(mid)) r = mid;\n\t\telse l = mid + 1;\n\t}\n\n\tstd::cout << l << std::endl;\n\treturn 0;\n}\n```\n\n E 正文"},{"aid":"85472","title":"扫地机器人（python）","date":"2022-03-19","likes":0,"views":1712,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-扫地机器人\n\n Server-side output Markdown text\n### 解题思路\n1. 找出机器人最小的打扫的格数， 为（格子数//机器人数）和第一个机器人的位置表示（因为第一个机器人左边的格子只能他自己去打扫）中的最大值\n\n2. 进行判断每个机器人都已这个作为打扫的大小能不能打扫完格子，如果不能就加一，再测试\n\n### 注意事项\n1. 机器人的打扫一定会打扫他开始在的那个格子\n\n### 代码\n```python\ndef ff(num1, num2):\n    ''''''\n    '''\n    :param num1: 已经打扫到的边界\n    :param num2: 每个机器人能打扫的格数\n    :return: True, False\n    '''\n    for i in range(0, k):\n        if a[i] - num2 <= num1:  # 机器人的位置 - 横扫的大小必须能够到达之前已经打扫的范围，否则就会有位置没有被打扫\n            if a[i] <= num1:  # 机器人的下标在已经打扫的范围内\n                num1 = a[i] + num2 - 1  # 已经打扫的范围就 + 能打扫的格数 - 1 （减一的作用是因为机器人本身会打扫自身的位置）\n            else:  # 机器人的下标不在已经打扫的范围内\n                num1 = a[i] + num2 - (a[i] - num1)  # 计算出最大的打扫范围，并且保证前面的格子都打扫了\n        else:\n            return False\n    if num1 < n:  # 没有打扫完\n        return False\n    return True\n\nn, k = list(map(int, input().split()))\na = [0 for i in range(k)]\nfor i in range(k):\n    a[i] = int(input())\na.sort()\ne = n // k if n // k >= a[0] else a[0]  # 最小清理的格数\nif n != k:  # 保证不是每个点都是机器人\n    while e <= n:\n        if ff(0, e):\n            break\n        e += 1\nprint(2 * (e - 1))  # 步数=（总共打扫的格数-1）*2\n```\n\n E 正文"},{"aid":"85155","title":"二分法求每个机器人的打扫范围","date":"2022-03-12","likes":0,"views":1003,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-扫地机器人\n\n Server-side output Markdown text\n```cpp\n#include<bits/stdc++.h>\nusing namespace std;\ntypedef long long ll;\nconst int N=1e5+5;\nint n,k,a[N];\nint check(int x){\n  int left=0;\n  for(int i=0;i<k;i++){\n    if(a[i]-x<=left){\n      if(a[i]<left){\n        left=a[i]+x-1;\n      } else {\n        left+=x;\n      }\n    } else {\n      return 0;\n    }\n  }\n  if(left<n){\n    return 0;\n  } else {\n    return 1;\n  }\n}\nint main()\n{\n  cin>>n>>k;\n  for(int i=0;i<k;i++){\n    cin>>a[i];\n  }\n  sort(a,a+k);\n  int l=0,r=n;\n  while(l<r){\n    int mid=l+(r-l)/2;\n    if(check(mid)){\n      r=mid;\n    } else {\n      l=mid+1;\n    }\n  }\n  cout<<(l-1)*2;\n  return 0;\n}\n\n```\n\n E 正文"},{"aid":"84568","title":"烂尾楼求解","date":"2022-02-28","likes":0,"views":561,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-扫地机器人\n\n Server-side output Markdown text\n# 问题描述\n![在这里插入图片描述](https://img-blog.csdnimg.cn/9884b126ae9d44ce8eb33a76850290cd.png?x-oss-process=image/watermark,type_d3F5LXplbmhlaQ,shadow_50,text_Q1NETiBA5aSp5aiB6Zq-5rWL,size_20,color_FFFFFF,t_70,g_se,x_16)\n\n# 算法思路\nQ ：**已清洁区域的边界。**以最左边作为基准，已经打扫好的区域数量，在最开始时候定义为 0。\nT ：**扫地机器人用时。**所以对于每个机器人来说，它的最大清洁范围就是左右两边的 （T / 2）的距离之内。\nx ： **机器人当前的坐标。**\n\n首先判断：\n\n**x - (T / 2) < Q**\n\n也就是说机器人的左清洁范围要在边界左边，不然就直接退出\n\n然后判断下来对于某个机器人，共有如下几种情况：\n\n1 机器人位置在边界右边，所以此时需要更新边界的范围，将边界更新到机器人打扫的右边界：\n\n**Q = x + （T / 2）**\n\n2 机器人位置在边界右边将边界更新到\n\n**Q = x + (T / 2)**\n\n所以在两种情况下，机器人都是运行到那个位置\n\n# 踩坑\n时间的话，一增加就是两倍的关系，不如范围好控制，所以在后面把时间 T 改为 Scope这么一个范围的关系\n# 源代码\n\n```python\ndef judge(Left_border, Scope):\n\n    for i in range(Number_machine):\n\n        if(position_machine[i] - Scope <= Left_border):\n            if(position_machine[i] <= Left_border):\n                Left_border = position_machine[i] + Scope - 1\n            else:\n                Left_border = Scope + Left_border\n        else:\n            return(0)\n\n    if(Left_border < Number_area):\n        return(0)\n    else:\n        return(1)\n\n# main\nglobal Left_scope\n(Number_area, Number_machine) = map(int, input().split())\nposition_machine = [0 for _ in range(Number_machine)]\n\nfor i in range(Number_machine):\n    temp = int(input())\n    position_machine.append(temp)\nposition_machine.sort()\n\nif((Number_area / Number_machine) >= position_machine[0]):\n    Scope = int(Number_area / Number_machine)\nelse:\n    Scope = position_machine[0]\n\nfor i in range(Scope, Number_area + 1):\n    Left_border = 0\n    if(judge(Left_border, i) == 1):\n        print(2 * (i - 1))\n        break\n\n```\n\n E 正文"},{"aid":"78420","title":"蓝桥杯2019年第十届真题-扫地机器人-题解（Python代码）","date":"2021-04-10","likes":0,"views":1822,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-扫地机器人\n\n已经AC\n参考:https://blog.dotcpp.com/a/68642 的思路用python写了一遍\n参考代码:\ndef judge(m,q):\n   for i in range(k):\n       if (a[i]-q) <= m:\n           if a[i]<= m:\n               m = a[i] + q -1\n           else:\n               m = a[i] + q -(a[i] - m)\n       else:\n           return 0\n   if m < n:\n       return 0\n   return 1\nn,k = map(int,input().split())\na=[0]*k\nfor i in range(k):\n   a[i]=int(input())\na.sort()\nif (n/k) >=a[0]:\n   q = int(n/k)\nelse:\n   q = a[0]\n\nfor i in range(q,n+1):\n   m = 0\n   if judge(m,i)==1:\n       print(2 * (i - 1))\n       break\n\n E 正文"}],"2311":[{"aid":"109441","title":"小白python系列-黄金分割","date":"2025-07-30","likes":0,"views":380,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-Fibonacci 数列与黄金分割\n\n解题思路:无\n\n注意事项:无\n\n参考代码:\na=int(input())\nif a>=20:\n   print(\"0.61803399\")\nelse:\n   z=[0, 1, 1]\n   for i in range(1, a):\n       z.append(z[i] + z[i+1])\n   print('%.8f' % (z[a] / z[a+1]))\n\n E 正文"},{"aid":"102767","title":"蓝桥杯2019年第十届省赛真题-Fibonacci 数列与黄金分割(Java)","date":"2024-02-19","likes":0,"views":568,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-Fibonacci 数列与黄金分割\n\n Server-side output Markdown text\n```java\nimport java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        if (n >= 20) {\n            System.out.println(0.61803399);\n        } else {\n            double a = Fibonacci(n);\n            double b = Fibonacci(n + 1);\n            System.out.printf(\"%.8f\", a / b);\n        }\n    }\n\n    public static int Fibonacci(int n) {\n        if (n < 3) {\n            return 1;\n        }\n        return Fibonacci(n - 1) + Fibonacci(n - 2);\n    }\n}\n```\n\n E 正文"},{"aid":"101279","title":"递归求解java","date":"2023-12-26","likes":0,"views":747,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-Fibonacci 数列与黄金分割\n\n解题思路:编写递归函数，在主函数中调用这个函数以便求得第n位与第n+1位的结果，将结果相除就ok啦\n\n注意事项:double与float的区别，java中float数据在第8位进行四舍五入，因此要用double，注意递归的时间限制\n\n参考代码:\nimport java.util.Scanner;\n\npublic class Main_2311 {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        if (N >= 20) {//经过测试发现N>=20时保留八位小数的结果都为0.61803399，只需计算N<20的数据即可\n            System.out.println(0.61803399);\n        } else {\n            double a = Fibonacci(N);\n            double b = Fibonacci(N + 1);\n            System.out.printf(\"%.8f\",  a / b);\n        }\n    }\n    public static double Fibonacci(int N) {\n        if (N<3) return 1;\n        return Fibonacci(N - 1) + Fibonacci(N - 2);\n    }\n}\n\n E 正文"},{"aid":"96840","title":"c语言代码解决问题","date":"2023-06-08","likes":0,"views":457,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-Fibonacci 数列与黄金分割\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<stdio.h>\ndouble f(int x)\n{\n    double c;\n    if (x == 1)\n        c = 1.0;\n    else if (x == 2)\n        c = 1.0;\n    else\n        c = f(x - 1) + f(x - 2);\n    return c;\n}\nint main()\n{\n    long long int n;\n    scanf(\"%lld\", &n);\n    if (n < 20)\n    {\n        printf(\"%.8lf\", f(n) / f(n + 1));\n    }\n    else\n        printf(\"0.61803399\");\n    return 0;\n}\n\n E 正文"},{"aid":"94942","title":"蓝桥杯专题系列-2311（Python）","date":"2023-03-16","likes":0,"views":562,"md":"S 正文\n原题链接：蓝桥杯2019年第十届省赛真题-Fibonacci 数列与黄金分割\n\n解题思路:多调试代码\n\n参考代码:\nn = int(input())\nlst = [1, 1, 2]\nif n == 1 :\n    print('1.00000000')\nelif n == 2 :\n    print('0.50000000')\nelse :\n    if n >= 20 :\n        print('0.61803399')\n    else :\n        for i in range(3, n + 1) :\n            lst.append(lst[1] + lst[2])\n            lst = lst[-3 :]\n        print('{:.8f}'.format(lst[-2] / lst[-1]))\n\n E 正文"}],"2557":[{"aid":"96509","title":"转换成每一步代价不等的最短路问题，采用优先队列（堆）解决","date":"2023-05-17","likes":0,"views":756,"md":"S 正文\n原题链接：蓝桥杯2019年第十届国赛真题-大胖子走迷宫\n\n解题思路:\n设堆顶的状态为x,y,fat,time。那么从x,y向四个方向搜索下一个点tx,ty时，有的方向会因为肥胖问题无法移动，这时我们减小身材，让他能达到tx,ty这个点（注意身材减小为1时，一定能自由的到达下一个点），可这个过程会导致一个问题,减小身材必须要原地等,因此若减小身材之后到达tx,ty这个点，那么这一步的代价不为1，所以我们无法用普通的队列，改用优先队列。如果还不理解，我举个例子：k=5,设四个方向的下一个点分别为1,2,3,4，且当前fat=5，time=1。其中1，2这两个点当前身材可以过去，那么就往堆里插入（1,fat,time+1），（2，fat,time+1)。3这个点只有当fat=3时可以过去，那么就先在原地等到5，再花费一个时间到达3，向堆里插入（3,3,6)，这就相当于从当前点花费了5个时间单位到达了3。同理，发现4必须身材为1时可以过去，那么就像堆里插入(4,1,11(2*k+1))，相当于花费了10个时间到达这一点。这就转化成了步长不同的bfs搜索了，直接上队列。\n\n注意事项:\n起点为3,3。不代表只能走(3,3)-(n-2,n-2)这个区域，别的区域也可以走，因为身材瘦了就可以走了。被这个bug卡了很久\n\n参考代码:\n#include <bits/stdc++.h>\nusing namespace std;\nconst int N=505;\nchar  a[N][N];\nint qz[N][N];\nint n,k;\nint dir[4][2]={{0,1},{1,0},{0,-1},{-1,0}};\nstruct rec{\n    int x,y,fat,time;\n    rec(){}\n    rec(int a,int b,int c,int  d)\n    {\n        x=a;\n        y=b;\n        fat=c;\n        time=d;\n    }\n    bool operator <(const rec &x) const\n    {\n        return time>x.time;\n    }\n};\nbool v[N][N];\npriority_queue<rec> q;\nint main()\n{\n    cin>>n>>k;\n    for(int i=1;i<=n;i++)\n        for(int j=1;j<=n;j++)\n    {\n        cin>>a[i][j];\n        qz[i][j]=qz[i-1][j]+qz[i][j-1]-qz[i-1][j-1]+(a[i][j]=='+'?1:0);\n    }\n    q.push(rec(3,3,5,0));\n    v[3][3]=1;\n    int cnt=0;\n    while(q.empty()==0)\n    {\n        rec temp=q.top();\n        q.pop();\n        /*\n        cnt++;\n        if(cnt>100) break;*/\n        //cout<<temp.x<<' '<<temp.y<<' '<<temp.fat<<' '<<temp.time<<endl;\n        if(temp.x==n-2&&temp.y==n-2) {cout<<temp.time<<endl;break;}\n        if(temp.time==k) temp.fat=3;\n        if(temp.time==2*k) temp.fat=1;\n        bool flag=0;\n        for(int d=0;d<4;d++)\n        {\n            int tx=temp.x+dir[d][0],ty=temp.y+dir[d][1];\n            if(tx>=1&&tx<=n-2&&ty>=1&&ty<=n-2&&v[tx][ty]==0)\n            {\n                int yxx=tx+temp.fat/2,yxy=ty+temp.fat/2,zsx=tx-temp.fat/2,zsy=ty-temp.fat/2;\n                if(qz[yxx][yxy]-qz[yxx][zsy-1]-qz[zsx-1][yxy]+qz[zsx-1][zsy-1]==temp.fat*temp.fat)\n                {\n                    v[tx][ty]=1;\n                    q.push(rec(tx,ty,temp.fat,temp.time+1));\n                    flag=1;\n                }\n                else\n                {\n                    if(temp.fat==5)\n                    {\n                        int yxx=tx+1,yxy=ty+1,zsx=tx-1,zsy=ty-1;\n                        if(qz[yxx][yxy]-qz[yxx][zsy-1]-qz[zsx-1][yxy]+qz[zsx-1][zsy-1]==3*3)\n                        {\n                            q.push(rec(tx,ty,3,k+1));\n                            v[tx][ty]=1;\n                            flag=1;\n                        }\n                        else\n                        {\n                            if(a[tx][ty]=='+')\n                            q.push(rec(tx,ty,1,2*k+1));\n                            v[tx][ty]=1;\n                            flag=1;\n                        }\n                    }\n                    else if(temp.fat==3)\n                    {\n                        if(a[tx][ty]=='+')\n                            {\n                                q.push(rec(tx,ty,1,2*k+1));\n                                v[tx][ty]=1;\n                                flag=1;\n                            }\n                    }\n                }\n\n            }\n        }\n    }\n    return 0;\n}\n\n E 正文"},{"aid":"95264","title":"蓝桥杯2019年第十届国赛真题-大胖子走迷宫","date":"2023-03-25","likes":0,"views":853,"md":"S 正文\n原题链接：蓝桥杯2019年第十届国赛真题-大胖子走迷宫\n\n解题思路:\n\n注意事项: 这个题和一般的迷宫问题不同在于可以呆在原地等待，vis[][]用于记录走过的位置，注意原地等待不用判断是否走过（因为一定已经走过）\n\n参考代码:\nimport java.util.LinkedList;\nimport java.util.Queue;\nimport java.util.Scanner;\npublic class 大胖子走迷宫 {\n    static int[] xx ={1,0,-1,0};\n    static int[] yy ={0,1,0,-1};\n    static boolean[][] vis;\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int n = scanner.nextInt();\n        int k = scanner.nextInt();\n        char[][] map = new char[n + 2][n + 2];\n        vis = new boolean[n + 2][n + 2];\n        for (int i = 1; i <= n; i++) {\n            String str = scanner.next();\n            for (int j = 1; j <= n; j++) {\n                map[i][j] = str.charAt(j - 1);\n            }\n        }\n        System.out.println(bfs(map,k,n));\n    }\n    public static int bfs(char[][]map,int k,int n){\n        Queue<int []> queue=new LinkedList<>();\n        queue.add(new int[]{3,3,0});\n        while (!queue.isEmpty()){\n            int[] now =queue.poll();\n            if(now[0]==n-2&&now[1]==n-2){\n                return now[2];\n            }\n            for(int i=0;i<=3;i++){\n                int dx=xx[i]+now[0];\n                int dy=yy[i]+now[1];\n                if(now[2]<k){\n                    if(dx<=n-2&&dx>=3&&dy>=3&&dy<=n-2&&!vis[dx][dy]){\n                        boolean can=true;\n                        for(int j=dx-2;j<=dx+2;j++){\n                            for(int p=dy-2;p<=dy+2;p++){\n                                if(map[j][p]=='*')\n                                {\n                                    can=false;\n                                    break;\n                                }\n                            }\n                        }\n                        if(can)\n                        {\n                            vis[dx][dy]=true;\n                            queue.add(new int[]{dx,dy,now[2]+1});\n                        }\n                    }\n                }\n                else if(now[2]<2*k&&now[2]>=k){\n                    if(dx<=n-1&&dx>=2&&dy>=2&&dy<=n-1&&!vis[dx][dy]){\n                        boolean can=true;\n                        for(int j=dx-1;j<=dx+1;j++){\n                            for(int p=dy-1;p<=dy+1;p++){\n                                if(map[j][p]=='*')\n                                {\n                                    can=false;\n                                    break;\n                                }\n                            }\n                        }\n                        if(can)\n                        {\n                            vis[dx][dy]=true;\n                            queue.add(new int[]{dx,dy,now[2]+1});\n                        }\n                    }\n                }\n                else {\n                    if(dx<=n&&dx>=1&&dy>=1&&dy<=n&&!vis[dx][dy]){\n                        if(map[dx][dy]!='*')\n                        {\n                            vis[dx][dy]=true;\n                            queue.add(new int[]{dx,dy,now[2]+1});\n                        }\n                    }\n                }\n            }\n            queue.add(new int[]{now[0],now[1],now[2]+1}); //增加原地等待选项\n        }\n        return -1;\n    }\n}\n\n E 正文"},{"aid":"88168","title":"bfs-大胖子走迷宫","date":"2022-06-11","likes":0,"views":887,"md":"S 正文\n原题链接：蓝桥杯2019年第十届国赛真题-大胖子走迷宫\n\n Server-side output Markdown text\n下方注释那地儿的判断条件不加在蓝桥oj没啥问题，但在这会超时\n吐槽一句，蓝桥给的解析甚至过不了自己的oj\n```cpp\n#include<bits/stdc++.h>\nusing namespace std;\ntypedef long long ll;\nconst int N=305;\nint n,k,ext=2,ans=10000000;\nchar mp[N][N];\nint vis[N][N];\nint dis[4][2]={0,1,0,-1,1,0,-1,0};\nstruct node {\n  int x,y,t;\n};\nbool check(int x,int y){\n  if(vis[x][y]) return false;\n  if(x-ext<1||x+ext>n||y-ext<1||y-ext>n){\n    return false;\n  }\n  for(int i=x-ext;i<=x+ext;i++){\n    for(int j=y-ext;j<=y+ext;j++){\n      if(mp[i][j]=='*') return false;\n    }\n  }\n  return true;\n}\nvoid bfs(){\n  queue<node> q;\n  q.push({3,3,0});\n  while(!q.empty()){\n    node tmp=q.front();\n    q.pop();\n    if(tmp.x==n-2&&tmp.y==n-2){\n      cout<<tmp.t;\n      return;\n    }\n    if(tmp.t<2*k) q.push({tmp.x,tmp.y,tmp.t+1});\t//不加判断会超时\n    if(tmp.t==k) ext=1;\n    if(tmp.t==2*k) ext=0;\n    for(int i=0;i<4;i++){\n      int tx=tmp.x+dis[i][0],ty=tmp.y+dis[i][1];\n      if(check(tx,ty)){\n        q.push({tx,ty,tmp.t+1});\n        vis[tx][ty]=1;\n      }\n    }\n  }\n}\nint main()\n{\n  cin>>n>>k;\n  if(n<=5){\n    cout<<0;\n    return 0;\n  }\n  for(int i=1;i<=n;i++){\n    scanf(\"%s\",mp[i]+1);\n  }\n  vis[3][3]=1;\n  bfs();\n  return 0;\n}\n\n```\n\n E 正文"},{"aid":"85542","title":"蓝桥杯2019年第十届国赛真题-大胖子走迷宫","date":"2022-03-21","likes":0,"views":1530,"md":"S 正文\n原题链接：蓝桥杯2019年第十届国赛真题-大胖子走迷宫\n\n解题思路:\nBFS  多加几个判断条件\n\n注意事项:\n\n当时间<2*k，可能原地不动，也可能动。\n\n当时间>=2*k之后，就不用原地不动了，直接走。\n\n参考代码:\n#include\"bits/stdc++.h\"\nusing namespace std;\nchar a[1000][1000];\nint v[1000][1000];\nint dx[]={0,1,0,-1};\nint dy[]={1,0,-1,0};\nint n;\nint k;\nint len;\nstruct node{\n\tint x;\n\tint y;\n\tint step;\n};\nqueue<node> q;\nbool check(int xx,int yy,int time){\n\tif(time<k)\n\tlen=2;\n\telse if(time>=k&&time<2*k)\n\tlen=1;\n\telse\n\tlen=0;\n\tfor(int i=xx-len;i<=xx+len;i++){\n\t\tfor(int j=yy-len;j<=yy+len;j++){\n\t            if(a[i][j]=='*')\n\t\t\t\treturn false;\n\t  }\n    }\n  if(xx<=0||yy<=0||xx>n||yy>n||v[xx][yy]==1||a[xx][yy]=='*')\n  return false;\n return true;\n}\nvoid bfs(int nx,int ny){\n\tnode pre;\n\tnode next;\n\tnode pree;\n\tpre.x=nx;\n\tpre.y=ny;\n\tpre.step=0;\n\tv[pre.x][pre.y]=1;\n\tq.push(pre);\n\twhile(q.size()){\n\t\tpre=q.front();\n\t\tq.pop();\n\n\t\tif(pre.x==n-2&&pre.y==n-2){\n\t\t\tcout<<pre.step;\n\t\t\treturn ;\n\t\t}\n\n\t\tif(pre.step<2*k ){            //原地不动\n\t\t pree.step=pre.step+1;\n\t\t pree.x=pre.x;\n\t\t pree.y=pre.y;\n\t\t q.push(pree);\n\t\t}\n\n\t\tfor(int i=0;i<4;i++){\n\t\t\tnext.x=pre.x+dx[i];\n\t\t\tnext.y=pre.y+dy[i];\n\t\t\tnext.step=pre.step;\n\t\t\tif(check(next.x,next.y,next.step)){    //能动\n\t\t\t\tv[next.x][next.y]=1;\n\t\t\t \t next.step=pre.step+1;\n\t\t\t\tq.push(next);\n\t\t\t}\n\t\t}\n \t}\n}\n\nint main(){\n\tcin>>n>>k;\n\tfor(int i=1;i<=n;i++){\n\t\tfor(int j=1;j<=n;j++){\n\t\t\tcin>>a[i][j];\n\t\t}\n\t}\n\n\tbfs(3,3);\n\treturn 0;\n}\n\n E 正文"}],"2558":[{"aid":"85641","title":"DFS+图查找 （Python-AC）","date":"2022-03-23","likes":0,"views":1009,"md":"S 正文\n原题链接：蓝桥杯2019年第十届国赛真题-估计人数\n\n解题思路:思路参考CSDN原博客：https://blog.csdn.net/jokerxsy/article/details/117561030?ops_request_misc=%257B%2522request%255Fid%2522%253A%2522164791572816780274160695%2522%252C%2522scm%2522%253A%252220140713.130102334.pc%255Fall.%2522%257D&request_id=164791572816780274160695&biz_id=0&utm_medium=distribute.pc_search_result.none-task-blog-2~all~first_rank_ecpm_v1~rank_v31_ecpm-4-117561030.142^v2^pc_search_result_control_group,143^v4^register&utm_term=%E4%BC%B0%E8%AE%A1%E4%BA%BA%E6%95%B0%E8%93%9D%E6%A1%A5%E6%9D%AF&spm=1018.2226.3001.4187\n\n首先明确这是个类似于无向图的概念，只不过这个所谓的无向图是有限制的\n注意事项:\n注重理解佛洛依德算法和用匈牙利算法来DFS\n\n参考代码:\n\n![](https://blog.dotcpp.com/uploads/20220323/1648016809416836.png)![](https://blog.dotcpp.com/uploads/20220323/1648016851159192.png)\n\n E 正文"}],"2559":[{"aid":"104003","title":"c++暴力枚举时间统计","date":"2024-03-30","likes":0,"views":605,"md":"S 正文\n原题链接：蓝桥杯2019年第十届国赛真题-轨道炮\n\n解题思路:枚举1000秒内所有情况，再利用map记录x y的最大情况\n\n注意事项:\n\n参考代码:\n#include<bits/stdc++.h>\n#define int long long\nusing namespace std;\nconst int N =1e3+5;\ntypedef pair<int,int> pii;//坐标\nint n,v[N];\npii m[N];\nchar h[N];\nint ans;\nsigned main()\n{\n   ios::sync_with_stdio(0);\n   cin.tie(0);\n   cout.tie(0);\n   cin>>n;\n   for(int i=0;i<n;i++){\n       int x,y;\n       cin>>x>>y>>v[i]>>h[i];\n       m[i]={x,y};\n   }\n   //暴力枚举所以时间的所以情况\n   for(int t=0;t<=1000;t++){\n       map<int,int> m_x,m_y;\n       int x_m=0,y_m=0;\n       for(int i=0;i<n;i++){\n           int x=m[i].first,y=m[i].second;\n           //U D L R\n           if(h[i]=='U'){y+=(v[i]*t);}\n           if(h[i]=='D'){y-=(v[i]*t);}\n           if(h[i]=='L'){x-=(v[i]*t);}\n           if(h[i]=='R'){x+=(v[i]*t);}\n           m_x[x]++,m_y[y]++;\n           x_m=max(x_m,m_x[x]);y_m=max(y_m,m_y[y]);\n       }\n       ans=max(ans,max(x_m,y_m));\n   }\n   cout<<ans<<endl;\n   return 0;\n}\n\n E 正文"},{"aid":"86044","title":"蓝桥杯VIP算法训练-轨道炮-看完秒懂的（c++map）","date":"2022-03-31","likes":0,"views":1144,"md":"S 正文\n原题链接：蓝桥杯2019年第十届国赛真题-轨道炮\n\n解题思路:\n轨道炮：\n\n看题找算法:\n\n典型map题目\n\n思路：\n\n1.首先横向射和纵向射是分立的问题，可以分别解决然后取最大值。\n\n2.单个方向上问题就是：给定初始位置和速度，求一个时间和位置使得在这个时间和位置上重合的点最多。\n\n3.因为n只有1000，两两求出相遇时间以及位置，取答案最大的时间和位置即可。\n\n注意事项:\n不要问，因为我也不会\n参考代码:\n#include\nusing namespace std;\nint X[1010],Y[1010],vx[1010],vy[1010];\nint mx=0;\nint n;\nvoid f(int X[],int vx[])\n{\n\n    for(int i=1;i<n;i++)\n    {\n        unordered_map\n        int cnt=1;\n        for(int j=i+1;j<=n;j++)\n        {\n            if(vx[i]==vx[j])\n            {\n                if(X[i]==X[j])\n                    cnt++;\n                mx=max(cnt,mx);\n                continue;\n            }\n            int dx=X[i]-X[j],dv=vx[j]-vx[i];\n            int t=dx/dv;\n            if(dx%dv||t<0)   continue;\n            m[t]++;\n            mx=max(mx,m[t]+cnt);\n        }\n    }\n}\nint main()\n{\n    cin>>n;\n    for(int i=1;i<=n;i++)\n    {\n        int v;\n        char d;\n        cin>>X[i]>>Y[i]>>v>>d;\n        if(d=='R')\n            vx[i]=v;\n        if(d=='L')\n            vx[i]=-v;\n        if(d=='U')\n            vy[i]=v;\n        if(d=='D')\n            vy[i]=-v;\n    }\n    f(X,vx);\n    f(Y,vy);\n    cout<<mx;\n    return 0;\n}\n\n E 正文"}],"2562":[{"aid":"89188","title":"蓝桥杯2019年第十届国赛真题-最优包含(动态规划)","date":"2022-08-02","likes":0,"views":802,"md":"S 正文\n原题链接：蓝桥杯2019年第十届国赛真题-最优包含\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\n\nint dp[1005][1005] = {0};\n\nint main()\n{\n    string s, t;\n    cin >> s >> t;\n    int m = s.size();\n    int n = t.size();\n    for (int i = 1; i <= m; i++) {\n        for (int j = 1; j <= n; j++) {\n            if (i >= j) {\n                if (s[i-1] == t[j-1]) {\n                    dp[i][j] = dp[i-1][j-1];\n                } else {\n                    dp[i][j] = dp[i-1][j-1] + 1;\n                    if (i-1 >= j) {\n                        dp[i][j] = min(dp[i][j], dp[i-1][j]);\n                    }\n                }\n            }\n        }\n    }\n    cout << dp[m][n] << endl;\n    return 0;\n}\n\n E 正文"},{"aid":"87913","title":"递归实现（动态规划,记忆化搜索）","date":"2022-05-28","likes":0,"views":1005,"md":"S 正文\n原题链接：蓝桥杯2019年第十届国赛真题-最优包含\n\n解题思路:\nf(i,j)返回d[i][j]，d[i][j]表示S前i个字符中包含T前j个字符至少修改的次数，因此答案将会是f(s_len,t_len)。i==0时修改j次，j==0时修改0次，j>i时修改f(i,j)+j-i次。计算d[i][j]时，若s[i]==t[j]，即当前考虑的两个字符串最后一个字符相等，此时d[i][j]=f(i-1,j-1)，否则，若最后一个字符不相等，d[i][j]=min(f(i-1,j),f(i-1,j-1)+1)。1、f(i-1,j)表示S前i-1个字符中包含T前j个字符至少修改的次数2、f(i-1,j-1)表示S前i-1个字符中包含T前j-1个字符至少修改的次数，加1是因为此时修改S的第i个字符，才能让S前i个字符中包含T前j个字符。最初将d中所有元素初始化为-1，因为修改次数肯定大于等于0，调用f函数时，若d[i][j]>=0，说明它已经算过，不再重复计算，直接返回。\n\n参考代码:\n#include<cstdio>\n#include<cstring>\n#include<algorithm>\n\nusing namespace std;\n\nchar s[1002],t[1002];\nint d[1001][1001];\n\nint f(int i,int j){\n    if(d[i][j]>=0){\n        return d[i][j];\n    }\n\n    if(i==0){\n        return d[i][j]=j;\n    }\n\n    if(j==0){\n        return d[i][j]=0;\n    }\n\n    if(j>i){\n        return d[i][j]=f(i,i)+j-i;\n    }\n\n    if(s[i]==t[j]){\n        return d[i][j]=f(i-1,j-1);\n    }\n    else{\n        return d[i][j]=min(f(i-1,j-1)+1,f(i-1,j));\n    }\n}\n\nint main(){\n\n    int s_len,t_len,i,j;\n\n    scanf(\"%s\",s+1);\n    scanf(\"%s\",t+1);\n    s_len=strlen(s+1);\n    t_len=strlen(t+1);\n\n    memset(d,-1,sizeof(d));\n\n    printf(\"%d\",f(s_len,t_len));\n\n    return 0;\n}\n\n E 正文"},{"aid":"84760","title":"蓝桥杯2019年第十届国赛真题-最优包含","date":"2022-03-04","likes":0,"views":1368,"md":"S 正文\n原题链接：蓝桥杯2019年第十届国赛真题-最优包含\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<iostream>\n#include<cstring>\n#include<algorithm>\nusing namespace std;\nint dp[1005][1005];\nchar s[1005], t[1005];\nint n, m;\nint main()\n{\n\tcin >> s + 1 >> t + 1;\n\tn = strlen(s + 1);\n\tm = strlen(t + 1);\n\tfor(int i=1;i<=n;i++)\n\t\tfor (int j = 1; j <=m&&i>=j; j++)\n\t\t{\n\t\t\tdp[i][j] = 1e9;\n\t\t\tif (i - 1 >= j)\n\t\t\t\tdp[i][j] = min(dp[i - 1][j], dp[i][j]);\n\t\t\tif (s[i] == t[j])\n\t\t\t\tdp[i][j] = min(dp[i][j], dp[i - 1][j - 1]);\n\t\t\telse\n\t\t\t\tdp[i][j] = min(dp[i][j],dp[i-1][j-1]+1);\n\t\t}\n\tcout << dp[n][m];\n\treturn 0;\n}\n\n E 正文"},{"aid":"84015","title":"动态规划--最优包含","date":"2022-02-14","likes":0,"views":1022,"md":"S 正文\n原题链接：蓝桥杯2019年第十届国赛真题-最优包含\n\n Server-side output Markdown text\n```cpp\n#include <iostream>\n#include <cstring>\nusing namespace std;\nconst int N=1005;\nint dp[N][N];\nint main()\n{\n  string s,t;\n  cin>>s>>t;\n  memset(dp,0x3f,sizeof(dp));\n  for(int i=0;i<=s.size();i++){\n    dp[i][0]=0;\n  }\n  for(int i=1;i<=s.size();i++){\n    for(int j=1;j<=t.size();j++){\n      if(s[i-1]==t[j-1]){\n        dp[i][j]=dp[i-1][j-1];\n      } else {\n        dp[i][j]=min(dp[i-1][j],dp[i-1][j-1]+1);\n      }\n    }\n  }\n  cout<<dp[s.size()][t.size()];\n  return 0;\n}\n```\n\n E 正文"},{"aid":"83616","title":"python-最优包含","date":"2022-02-07","likes":0,"views":1098,"md":"S 正文\n原题链接：蓝桥杯2019年第十届国赛真题-最优包含\n\n解题思路:\n动态规划。\n①创建一个大小为(n+1)*(m+1)的二维数组，命名为dp，n和m分别为字符串s、t的长度。\n   其中dp[i][j]表示s中的前i个字符要想包含t的前j个字符最少需要修改几次。\n②dp[i][0] = 0（i = 0 to n）\n③状态转移方程\n   当s[i] = t[j]时，这时我们不用进行变换则，dp[i][j] = dp[i-1][j-1]\n   当s[i] != t[j]时，这时有两种情况，一种情况是，在s中没取到第i个字符时，已经可以包含t取到字符j了。\n                                                       另一种情况是，此时t取到第j个字符时还未被包含，那么在此时，就要进行一次变换\n   所以dp[i][j] = min(dp[i-1][j]，dp[i-1][j-1]+1)\n\n注意事项:\n\n参考代码:\nfrom cmath import inf\n\ns = input().strip()\nt = input().strip()\nn = len(s)\nm = len(t)\n\ndp = [[inf for j in range(m+1)] for i in range(n+1)]\nfor i in range(n+1):\n    dp[i][0] = 0\n\nfor i in range(1,n+1):\n    for j in range(1,m+1):\n        if s[i-1] == t[j-1]:\n            dp[i][j] = dp[i-1][j-1]\n        else:\n            dp[i][j] = min(dp[i-1][j],dp[i-1][j-1]+1)\nprint(dp[n][m])\n\n E 正文"}]};